__CR('t:numpy',[{"t":"ndarray 기초","l":[{"t":"배열 생성과 shape/ndim/dtype","q":[{"t":"choice","k":"타입","q":"파이썬 리스트를 np.array()에 넣어 만들면 결과는 어떤 타입인가?","o":["ndarray","list","tuple","dict"],"a":0,"ex":"np.array()는 NumPy의 핵심 자료구조인 ndarray 객체를 반환합니다."},{"t":"input","k":"shape","q":"아래 코드의 출력은?","code":"a = np.array([[1,2,3],[4,5,6]])\nprint(a.shape)","a":["(2, 3)","(2,3)"],"ex":"2행 3열이므로 shape는 (2, 3)입니다. shape는 (행, 열) 순서의 tuple입니다."},{"t":"choice","k":"dtype","q":"np.array([1, 2, 3])의 기본 dtype는? (64bit 환경)","o":["int64","float64","int32","object"],"a":0,"ex":"정수 리스트로 만들면 기본 dtype는 int64입니다. 실수가 하나라도 있으면 float64가 됩니다."},{"t":"input","k":"size","q":"2행 3열 배열 a의 총 원소 개수를 반환하는 a.size 값은?","code":"a = np.array([[1,2,3],[4,5,6]])\nprint(a.size)","a":["6"],"ex":"size는 전체 원소 개수로 2 × 3 = 6입니다. shape의 곱과 같습니다."}],"th":{"sum":"**ndarray**는 같은 dtype 원소를 담는 다차원 배열이다. `shape`(모양), `ndim`(차원 수), `dtype`(자료형)으로 구조를 파악한다.","body":[{"h":"배열 생성과 속성","t":"`np.array([1,2,3])`은 파이썬 리스트를 **ndarray**로 바꾸며 64bit 환경 기본 dtype은 `int64`다. `np.array([[1,2],[3,4]])`처럼 중첩 리스트는 ndim=2가 된다. `a.size`는 총 원소 개수, `a.shape`은 (행,열) 튜플을 반환한다."},{"h":"생성 함수와 슬라이싱","t":"`np.arange(0,10,2)`는 `[0 2 4 6 8]`, `np.linspace(0,1,5)`는 0~1을 5등분한 `[0. 0.25 0.5 0.75 1.]`를 만든다. 슬라이싱은 복사가 아닌 **뷰(view)**를 반환하므로 슬라이스를 수정하면 원본도 바뀐다. `astype`으로 dtype을 변환한다."}],"code":{"c":"import numpy as np\na = np.arange(0, 10, 2)      # [0 2 4 6 8]\nb = np.linspace(0, 1, 5)     # [0. 0.25 0.5 0.75 1.]\nprint(a.dtype, a.shape, a.ndim)  # int64 (5,) 1","cap":"arange는 간격 지정, linspace는 개수 지정, 슬라이스는 뷰"},"key":["ndarray는 동일 dtype 다차원 배열","기본 정수 dtype은 int64 (64bit 환경)","arange=간격 지정, linspace=개수 지정(끝값 포함)","슬라이싱은 뷰 — 수정 시 원본도 변경"]}},{"t":"배열 생성 함수와 reshape","q":[{"t":"choice","k":"arange","q":"np.arange(0, 10, 2)의 출력은?","o":["[0 2 4 6 8]","[0 2 4 6 8 10]","[2 4 6 8]","[0 1 2 ... 9]"],"a":0,"ex":"arange(시작, 끝, 간격)은 0부터 2씩 증가하며 끝값 10은 포함하지 않으므로 [0 2 4 6 8]입니다."},{"t":"input","k":"linspace","q":"np.linspace(0, 1, 5)의 세 번째 값(인덱스 2)은?","a":["0.5"],"ex":"linspace(시작, 끝, 개수)는 끝값을 포함해 균등 분할합니다. [0, 0.25, 0.5, 0.75, 1] 중 인덱스 2는 0.5입니다."},{"t":"input","k":"reshape","q":"아래 코드의 출력은?","code":"a = np.arange(12).reshape(3, 4)\nprint(a.shape)","a":["(3, 4)","(3,4)"],"ex":"arange(12)로 0~11의 1차원 배열을 만든 뒤 3행 4열로 reshape하므로 shape는 (3, 4)입니다. 원소 수 12가 3×4와 일치해야 합니다."}],"th":{"sum":"**ndarray**는 같은 dtype 원소를 담는 다차원 배열이다. `shape`(모양), `ndim`(차원 수), `dtype`(자료형)으로 구조를 파악한다.","body":[{"h":"배열 생성과 속성","t":"`np.array([1,2,3])`은 파이썬 리스트를 **ndarray**로 바꾸며 64bit 환경 기본 dtype은 `int64`다. `np.array([[1,2],[3,4]])`처럼 중첩 리스트는 ndim=2가 된다. `a.size`는 총 원소 개수, `a.shape`은 (행,열) 튜플을 반환한다."},{"h":"생성 함수와 슬라이싱","t":"`np.arange(0,10,2)`는 `[0 2 4 6 8]`, `np.linspace(0,1,5)`는 0~1을 5등분한 `[0. 0.25 0.5 0.75 1.]`를 만든다. 슬라이싱은 복사가 아닌 **뷰(view)**를 반환하므로 슬라이스를 수정하면 원본도 바뀐다. `astype`으로 dtype을 변환한다."}],"code":{"c":"import numpy as np\na = np.arange(0, 10, 2)      # [0 2 4 6 8]\nb = np.linspace(0, 1, 5)     # [0. 0.25 0.5 0.75 1.]\nprint(a.dtype, a.shape, a.ndim)  # int64 (5,) 1","cap":"arange는 간격 지정, linspace는 개수 지정, 슬라이스는 뷰"},"key":["ndarray는 동일 dtype 다차원 배열","기본 정수 dtype은 int64 (64bit 환경)","arange=간격 지정, linspace=개수 지정(끝값 포함)","슬라이싱은 뷰 — 수정 시 원본도 변경"]}},{"t":"인덱싱, 슬라이싱(뷰), astype","q":[{"t":"choice","k":"뷰","q":"NumPy 배열의 슬라이싱 결과는 뷰(view)입니다. 슬라이스를 수정하면 원본은?","o":["함께 변경된다","변경되지 않는다","오류가 난다","복사본이라 무관하다"],"a":0,"ex":"슬라이싱은 데이터를 복사하지 않고 원본을 공유하는 뷰입니다. 뷰를 수정하면 원본도 바뀝니다."},{"t":"choice","k":"뷰 수정","q":"아래 코드의 출력은?","code":"a = np.array([0,1,2,3,4])\nb = a[1:4]\nb[0] = 99\nprint(a)","o":["[ 0 99  2  3  4]","[0 1 2 3 4]","[99  1  2  3  4]","[ 0 99  2  3]"],"a":0,"ex":"b는 a[1:4]의 뷰이므로 b[0] = 99는 a[1]을 99로 바꿉니다. 따라서 원본 a는 [ 0 99  2  3  4]가 됩니다."},{"t":"input","k":"슬라이싱","q":"아래 코드의 출력은?","code":"a = np.arange(10)\nprint(a[2:5])","a":["[2 3 4]"],"ex":"인덱스 2부터 5 직전(2,3,4)까지 선택하므로 [2 3 4]입니다. 끝 인덱스는 포함되지 않습니다."},{"t":"choice","k":"copy","q":"슬라이싱해도 원본이 바뀌지 않게 하려면?","o":[".copy()로 복사한다","슬라이싱을 두 번 한다","astype을 쓴다","reshape을 쓴다"],"a":0,"ex":"a[1:4].copy()처럼 .copy()를 쓰면 원본과 분리된 새 배열이 만들어져 원본이 보호됩니다."},{"t":"choice","k":"astype","q":"np.array([1.7, 2.3]).astype(int)의 출력은?","o":["[1 2]","[2 2]","[1 3]","[2 3]"],"a":0,"ex":"astype(int)는 반올림이 아니라 소수부를 버립니다(0 방향 절삭). 1.7→1, 2.3→2이므로 [1 2]입니다."}],"th":{"sum":"**ndarray**는 같은 dtype 원소를 담는 다차원 배열이다. `shape`(모양), `ndim`(차원 수), `dtype`(자료형)으로 구조를 파악한다.","body":[{"h":"배열 생성과 속성","t":"`np.array([1,2,3])`은 파이썬 리스트를 **ndarray**로 바꾸며 64bit 환경 기본 dtype은 `int64`다. `np.array([[1,2],[3,4]])`처럼 중첩 리스트는 ndim=2가 된다. `a.size`는 총 원소 개수, `a.shape`은 (행,열) 튜플을 반환한다."},{"h":"생성 함수와 슬라이싱","t":"`np.arange(0,10,2)`는 `[0 2 4 6 8]`, `np.linspace(0,1,5)`는 0~1을 5등분한 `[0. 0.25 0.5 0.75 1.]`를 만든다. 슬라이싱은 복사가 아닌 **뷰(view)**를 반환하므로 슬라이스를 수정하면 원본도 바뀐다. `astype`으로 dtype을 변환한다."}],"code":{"c":"import numpy as np\na = np.arange(0, 10, 2)      # [0 2 4 6 8]\nb = np.linspace(0, 1, 5)     # [0. 0.25 0.5 0.75 1.]\nprint(a.dtype, a.shape, a.ndim)  # int64 (5,) 1","cap":"arange는 간격 지정, linspace는 개수 지정, 슬라이스는 뷰"},"key":["ndarray는 동일 dtype 다차원 배열","기본 정수 dtype은 int64 (64bit 환경)","arange=간격 지정, linspace=개수 지정(끝값 포함)","슬라이싱은 뷰 — 수정 시 원본도 변경"]}}]},{"t":"벡터화와 브로드캐스팅","l":[{"t":"벡터화 연산","q":[{"t":"choice","k":"스칼라 곱","q":"np.array([1, 2, 3]) * 2의 출력은?","o":["[2 4 6]","[1 2 3 1 2 3]","[2 2 2]","[1 4 9]"],"a":0,"ex":"리스트와 달리 배열 * 2는 각 원소에 2를 곱하는 요소별 연산입니다. [2 4 6]."},{"t":"choice","k":"속도","q":"동일한 요소별 연산에서 벡터화 연산은 파이썬 for 반복문보다 일반적으로?","o":["훨씬 빠르다","훨씬 느리다","항상 같다","오류가 난다"],"a":0,"ex":"벡터화 연산은 C 레벨에서 한 번에 처리하고 반복 오버헤드가 없어 파이썬 반복문보다 훨씬 빠릅니다."},{"t":"input","k":"제곱","q":"아래 코드의 출력은?","code":"a = np.array([1,2,3,4])\nprint(a ** 2)","a":["[ 1  4  9 16]"],"ex":"** 2는 각 원소를 제곱합니다. [1, 4, 9, 16]이며, 자리수를 맞춰 [ 1  4  9 16]로 출력됩니다."}],"th":{"sum":"**벡터화**는 파이썬 반복문 없이 배열 전체에 연산을 적용해 빠르고, **브로드캐스팅**은 모양이 다른 배열을 자동 확장해 원소별 연산을 가능하게 한다.","body":[{"h":"벡터화 연산","t":"`np.array([1,2,3])+10`은 `[11 12 13]`, `*2`는 `[2 4 6]`처럼 모든 원소에 한 번에 적용된다. C로 구현된 반복이라 파이썬 for 문보다 일반적으로 **훨씬 빠르다**. `+ - * /`는 요소별(element-wise) 연산이며, 행렬곱은 `@` 또는 `np.dot`을 쓴다."},{"h":"브로드캐스팅 규칙","t":"모양이 다른 배열을 연산할 때 뒤 차원부터 비교해 크기가 1이거나 같으면 자동으로 늘려 맞춘다. 예를 들어 (2,3) 배열과 (3,) 배열을 더하면 (3,)이 각 행에 브로드캐스트된다. 스칼라 덧셈도 브로드캐스팅의 특수한 경우다."}],"code":{"c":"import numpy as np\na = np.array([[1, 2, 3], [4, 5, 6]])\nb = np.array([10, 20, 30])\nprint(a + b)   # [[11 22 33]\n               #  [14 25 36]]  (3,)가 각 행에 브로드캐스트","cap":"(2,3)+(3,): 작은 배열이 각 행으로 자동 확장"},"key":["벡터화는 for 문보다 훨씬 빠름 (C 구현)","+ - * /는 요소별 연산, 행렬곱은 @ / np.dot","브로드캐스팅: 뒤 차원부터 1이거나 같으면 자동 확장","스칼라 연산도 브로드캐스팅의 한 형태"]}},{"t":"브로드캐스팅 규칙","q":[{"t":"choice","k":"불일치","q":"shape (2,3) 배열과 (2,) 배열을 더하면?","o":["오류가 난다","(2,3)이 된다","(2,2)가 된다","(3,3)이 된다"],"a":0,"ex":"뒤 차원부터 비교할 때 3과 2가 맞지 않고 둘 다 1이 아니므로 브로드캐스팅 불가로 오류가 납니다. (2,1)이었다면 가능합니다."},{"t":"input","k":"결과 shape","q":"shape (4,1) 배열과 (3,) 배열을 더할 때 결과 shape는? (예: (2, 2))","a":["(4, 3)","(4,3)"],"ex":"(4,1)과 (3,)=(1,3)을 비교하면 각 차원에서 1이 상대에 맞춰 확장되어 (4, 3)이 됩니다."}],"th":{"sum":"**벡터화**는 파이썬 반복문 없이 배열 전체에 연산을 적용해 빠르고, **브로드캐스팅**은 모양이 다른 배열을 자동 확장해 원소별 연산을 가능하게 한다.","body":[{"h":"벡터화 연산","t":"`np.array([1,2,3])+10`은 `[11 12 13]`, `*2`는 `[2 4 6]`처럼 모든 원소에 한 번에 적용된다. C로 구현된 반복이라 파이썬 for 문보다 일반적으로 **훨씬 빠르다**. `+ - * /`는 요소별(element-wise) 연산이며, 행렬곱은 `@` 또는 `np.dot`을 쓴다."},{"h":"브로드캐스팅 규칙","t":"모양이 다른 배열을 연산할 때 뒤 차원부터 비교해 크기가 1이거나 같으면 자동으로 늘려 맞춘다. 예를 들어 (2,3) 배열과 (3,) 배열을 더하면 (3,)이 각 행에 브로드캐스트된다. 스칼라 덧셈도 브로드캐스팅의 특수한 경우다."}],"code":{"c":"import numpy as np\na = np.array([[1, 2, 3], [4, 5, 6]])\nb = np.array([10, 20, 30])\nprint(a + b)   # [[11 22 33]\n               #  [14 25 36]]  (3,)가 각 행에 브로드캐스트","cap":"(2,3)+(3,): 작은 배열이 각 행으로 자동 확장"},"key":["벡터화는 for 문보다 훨씬 빠름 (C 구현)","+ - * /는 요소별 연산, 행렬곱은 @ / np.dot","브로드캐스팅: 뒤 차원부터 1이거나 같으면 자동 확장","스칼라 연산도 브로드캐스팅의 한 형태"]}},{"t":"행렬곱과 비교연산","q":[{"t":"choice","k":"dot","q":"np.dot([1,2,3], [4,5,6])의 결과는?","o":["32","[4 10 18]","[5 7 9]","15"],"a":0,"ex":"1차원끼리 np.dot은 내적입니다. 1×4 + 2×5 + 3×6 = 4+10+18 = 32."},{"t":"input","k":"내적","q":"np.dot([1,2], [3,4])의 결과 값은?","a":["11"],"ex":"1×3 + 2×4 = 3 + 8 = 11입니다."}],"th":{"sum":"**벡터화**는 파이썬 반복문 없이 배열 전체에 연산을 적용해 빠르고, **브로드캐스팅**은 모양이 다른 배열을 자동 확장해 원소별 연산을 가능하게 한다.","body":[{"h":"벡터화 연산","t":"`np.array([1,2,3])+10`은 `[11 12 13]`, `*2`는 `[2 4 6]`처럼 모든 원소에 한 번에 적용된다. C로 구현된 반복이라 파이썬 for 문보다 일반적으로 **훨씬 빠르다**. `+ - * /`는 요소별(element-wise) 연산이며, 행렬곱은 `@` 또는 `np.dot`을 쓴다."},{"h":"브로드캐스팅 규칙","t":"모양이 다른 배열을 연산할 때 뒤 차원부터 비교해 크기가 1이거나 같으면 자동으로 늘려 맞춘다. 예를 들어 (2,3) 배열과 (3,) 배열을 더하면 (3,)이 각 행에 브로드캐스트된다. 스칼라 덧셈도 브로드캐스팅의 특수한 경우다."}],"code":{"c":"import numpy as np\na = np.array([[1, 2, 3], [4, 5, 6]])\nb = np.array([10, 20, 30])\nprint(a + b)   # [[11 22 33]\n               #  [14 25 36]]  (3,)가 각 행에 브로드캐스트","cap":"(2,3)+(3,): 작은 배열이 각 행으로 자동 확장"},"key":["벡터화는 for 문보다 훨씬 빠름 (C 구현)","+ - * /는 요소별 연산, 행렬곱은 @ / np.dot","브로드캐스팅: 뒤 차원부터 1이거나 같으면 자동 확장","스칼라 연산도 브로드캐스팅의 한 형태"]}}]},{"t":"집계와 마스킹","l":[{"t":"집계 함수와 axis","q":[{"t":"choice","k":"sum","q":"np.array([1,2,3,4]).sum()의 결과는?","o":["10","[1 2 3 4]","4","24"],"a":0,"ex":"axis를 지정하지 않은 sum()은 전체 원소를 더합니다. 1+2+3+4 = 10."},{"t":"input","k":"mean","q":"아래 코드의 출력은?","code":"a = np.array([[1,2,3],[4,5,6]])\nprint(a.mean())","a":["3.5"],"ex":"axis 없는 mean()은 전체 평균입니다. 합 21을 원소 수 6으로 나눠 3.5입니다."}],"th":{"sum":"집계 함수는 `axis`로 방향을 정하고, **boolean 마스킹**으로 조건에 맞는 원소만 고른다. `np.where`는 조건 분기, `argmax`/`argmin`은 최대·최소 위치를 반환한다.","body":[{"h":"axis와 집계","t":"`sum()`,`mean()`,`max()` 등은 전체 또는 축별로 집계한다. 2차원에서 **axis=0은 행 방향으로 내려가며 열별 집계**(세로), **axis=1은 열 방향으로 가로질러 행별 집계**를 한다. axis를 생략하면 전체 원소를 집계한다."},{"h":"마스킹과 where","t":"`a[a>2]`는 조건이 True인 원소만 골라 1차원으로 반환한다(boolean 마스킹). `np.where(조건, x, y)`는 조건이 참이면 x, 거짓이면 y를 원소별로 선택한다. `argmax`/`argmin`은 최댓값·최솟값의 **인덱스**를 돌려준다."}],"code":{"c":"import numpy as np\nm = np.array([[1, 2, 3], [4, 5, 6]])\nprint(m.sum(axis=0))   # [5 7 9]  열별 합\nprint(m.sum(axis=1))   # [6 15]   행별 합\nprint(m[m > 3])        # [4 5 6]  마스킹","cap":"axis=0은 열별(세로), axis=1은 행별(가로) 집계"},"key":["axis=0=열별(세로) 집계, axis=1=행별(가로) 집계","boolean 마스킹 `a[a>k]`는 조건 True 원소만 1차원 반환","np.where(조건,x,y)로 원소별 조건 분기","argmax/argmin은 값이 아니라 위치(인덱스) 반환"]}},{"t":"boolean 마스킹","q":[{"t":"choice","k":"개념","q":"boolean 마스킹 arr[조건]은 무엇을 하는가?","o":["조건이 True인 원소만 골라 추출한다","조건이 False인 원소를 삭제 후 저장한다","배열을 정렬한다","배열 크기를 바꾼다"],"a":0,"ex":"boolean 배열로 인덱싱하면 True에 해당하는 원소만 뽑아 새 1차원 배열로 반환합니다."},{"t":"input","k":"마스킹 값","q":"아래 코드의 출력은?","code":"a = np.array([5,3,8,1])\nprint(a[a &gt; 4])","a":["[5 8]"],"ex":"a &gt; 4는 [T F T F]이므로 4보다 큰 5와 8만 추출되어 [5 8]입니다."}],"th":{"sum":"집계 함수는 `axis`로 방향을 정하고, **boolean 마스킹**으로 조건에 맞는 원소만 고른다. `np.where`는 조건 분기, `argmax`/`argmin`은 최대·최소 위치를 반환한다.","body":[{"h":"axis와 집계","t":"`sum()`,`mean()`,`max()` 등은 전체 또는 축별로 집계한다. 2차원에서 **axis=0은 행 방향으로 내려가며 열별 집계**(세로), **axis=1은 열 방향으로 가로질러 행별 집계**를 한다. axis를 생략하면 전체 원소를 집계한다."},{"h":"마스킹과 where","t":"`a[a>2]`는 조건이 True인 원소만 골라 1차원으로 반환한다(boolean 마스킹). `np.where(조건, x, y)`는 조건이 참이면 x, 거짓이면 y를 원소별로 선택한다. `argmax`/`argmin`은 최댓값·최솟값의 **인덱스**를 돌려준다."}],"code":{"c":"import numpy as np\nm = np.array([[1, 2, 3], [4, 5, 6]])\nprint(m.sum(axis=0))   # [5 7 9]  열별 합\nprint(m.sum(axis=1))   # [6 15]   행별 합\nprint(m[m > 3])        # [4 5 6]  마스킹","cap":"axis=0은 열별(세로), axis=1은 행별(가로) 집계"},"key":["axis=0=열별(세로) 집계, axis=1=행별(가로) 집계","boolean 마스킹 `a[a>k]`는 조건 True 원소만 1차원 반환","np.where(조건,x,y)로 원소별 조건 분기","argmax/argmin은 값이 아니라 위치(인덱스) 반환"]}},{"t":"np.where와 argmax/argmin","q":[{"t":"choice","k":"argmax","q":"np.argmax([3, 1, 7, 2])의 결과는?","o":["2","7","0","3"],"a":0,"ex":"argmax는 최댓값의 인덱스를 반환합니다. 최댓값 7은 인덱스 2에 있으므로 2입니다."},{"t":"choice","k":"argmin","q":"np.argmin([3, 1, 7, 2])의 결과는?","o":["1","0","3","2"],"a":0,"ex":"argmin은 최솟값의 인덱스를 반환합니다. 최솟값 1은 인덱스 1에 있으므로 1입니다."},{"t":"input","k":"argmax 값","q":"np.argmax([10, 50, 30, 20])의 결과 값은?","a":["1"],"ex":"최댓값 50이 인덱스 1에 있으므로 argmax는 1을 반환합니다."}],"th":{"sum":"집계 함수는 `axis`로 방향을 정하고, **boolean 마스킹**으로 조건에 맞는 원소만 고른다. `np.where`는 조건 분기, `argmax`/`argmin`은 최대·최소 위치를 반환한다.","body":[{"h":"axis와 집계","t":"`sum()`,`mean()`,`max()` 등은 전체 또는 축별로 집계한다. 2차원에서 **axis=0은 행 방향으로 내려가며 열별 집계**(세로), **axis=1은 열 방향으로 가로질러 행별 집계**를 한다. axis를 생략하면 전체 원소를 집계한다."},{"h":"마스킹과 where","t":"`a[a>2]`는 조건이 True인 원소만 골라 1차원으로 반환한다(boolean 마스킹). `np.where(조건, x, y)`는 조건이 참이면 x, 거짓이면 y를 원소별로 선택한다. `argmax`/`argmin`은 최댓값·최솟값의 **인덱스**를 돌려준다."}],"code":{"c":"import numpy as np\nm = np.array([[1, 2, 3], [4, 5, 6]])\nprint(m.sum(axis=0))   # [5 7 9]  열별 합\nprint(m.sum(axis=1))   # [6 15]   행별 합\nprint(m[m > 3])        # [4 5 6]  마스킹","cap":"axis=0은 열별(세로), axis=1은 행별(가로) 집계"},"key":["axis=0=열별(세로) 집계, axis=1=행별(가로) 집계","boolean 마스킹 `a[a>k]`는 조건 True 원소만 1차원 반환","np.where(조건,x,y)로 원소별 조건 분기","argmax/argmin은 값이 아니라 위치(인덱스) 반환"]}}]},{"t":"브로드캐스팅 규칙 — shape가 저절로 맞춰지는 원리","l":[{"t":"브로드캐스팅 3단계 규칙","q":[{"t":"choice","k":"비교 방향","q":"NumPy가 두 배열의 shape를 브로드캐스팅할 때 축을 비교하는 순서는?","ex":"브로드캐스팅은 항상 shape의 뒤(오른쪽) 끝에서부터 축을 하나씩 맞춰 나간다. 앞에서부터 비교한다고 착각하면 (5,4)와 (4,)가 왜 되는지 설명할 수 없다. 원소 개수 총합은 브로드캐스팅과 아무 관계가 없다.","o":["앞(왼쪽) 축부터 차례로 비교한다","뒤(오른쪽) 축부터 차례로 비교한다","축 개수가 많은 쪽을 기준으로 무작위로 비교한다","shape는 무시하고 전체 원소 개수만 비교한다"],"a":1},{"t":"choice","k":"차원 보충","q":"두 배열의 차원 수가 다를 때 NumPy는 어떻게 처리하는가?","ex":"차원 수가 부족한 쪽의 shape 앞(왼쪽)에 1이 채워진다. (3,1)은 (2,3,4)와 만날 때 (1,3,1)로 취급된다. 뒤에 채우면 축의 의미가 뒤바뀌므로 NumPy는 절대 그렇게 하지 않는다.","o":["shape의 뒤(오른쪽)에 1을 채워 길이를 맞춘다","차원 수가 다르면 무조건 ValueError를 낸다","shape의 앞(왼쪽)에 1을 채워 길이를 맞춘다","가운데에 1을 끼워 넣어 길이를 맞춘다"],"a":2},{"t":"choice","k":"호환 조건","q":"각 축에서 두 크기가 브로드캐스팅 호환으로 인정되는 조건은?","ex":"축별 규칙은 단 두 가지다. 크기가 같거나, 한쪽이 1이면 호환된다. 배수 관계는 아무 의미가 없어서 (2,)와 (4,)는 배수여도 ValueError다.","o":["두 크기가 같거나, 한쪽이 1일 때","두 크기가 모두 1일 때만","한쪽이 다른 쪽의 배수일 때","두 크기의 합이 짝수일 때"],"a":0},{"t":"input","k":"shape 계산","q":"shape가 (3,1)인 배열과 (1,4)인 배열을 더하면 결과 shape는? (예: (2, 5) 형태로 답)","ex":"뒤에서부터 1 vs 4를 비교해 1이 4로 늘어나고, 3 vs 1을 비교해 1이 3으로 늘어난다. 양쪽 모두 1을 가지고 있어 서로 확장되므로 결과는 (3, 4)가 된다.","code":"import numpy as np\na = np.ones((3, 1))\nb = np.ones((1, 4))\nprint((a + b).shape)","a":["(3, 4)","(3,4)","3, 4","3,4"]},{"t":"choice","k":"1차원 충돌","q":"np.ones((3,)) + np.ones((4,)) 의 결과는?","ex":"뒤에서부터 3과 4를 비교하는데 둘 다 1이 아니고 서로 다르므로 ValueError다. 1차원끼리는 자동으로 2차원 격자가 만들어지지 않는다. (3,4)를 얻고 싶다면 한쪽을 [:, None]으로 (3,1)로 만들어야 한다.","o":["(3, 4) shape 배열","(4,) shape 배열","(12,) shape 배열","ValueError가 발생한다"],"a":3}],"th":{"sum":"브로드캐스팅은 shape가 다른 배열끼리 연산할 때 NumPy가 자동으로 축을 맞춰 주는 규칙이다. 두 shape를 뒤에서부터 축 단위로 비교해, 같거나 한쪽이 1이면 늘려서 맞춘다.","body":[{"h":"뒤(오른쪽)에서부터 비교한다","t":"브로드캐스팅은 두 배열의 shape를 **뒤(오른쪽)에서부터** 축 단위로 하나씩 비교한다. 앞(왼쪽)부터 비교하는 것이 아니라는 점이 가장 흔한 오해다. 예를 들어 `(5,4)`와 `(4,)`를 비교하면 마지막 축끼리 4와 4가 만나 호환되고 결과는 `(5,4)`가 된다."},{"h":"차원 수가 다르면 앞에 1을 채운다","t":"두 배열의 차원 개수가 다르면 부족한 쪽 shape의 **앞(왼쪽)**에 1을 채워 길이를 맞춘 뒤 비교를 시작한다. `(2,3,4)`와 `(3,1)`이면 뒤쪽이 `(1,3,1)`로 확장된다. 그 다음 축별로 4 vs 1, 3 vs 3, 2 vs 1을 비교해 결과는 `(2,3,4)`가 된다."},{"h":"각 축은 같거나 1이어야 한다","t":"축별 크기가 서로 같으면 그대로 두고, 한쪽이 1이면 상대 크기만큼 늘린다(stretch). 둘 다 1이 아니면서 크기가 다르면 ValueError가 난다. `(3,)`와 `(4,)`는 3과 4가 만나 어느 쪽도 1이 아니므로 에러이고, `(3,1)`과 `(1,4)`는 양쪽 모두 1이 있어 `(3,4)`로 늘어난다."},{"h":"데이터는 실제로 복제되지 않는다","t":"브로드캐스팅은 작은 배열을 물리적으로 복제하지 않고 해당 축의 stride를 0으로 두어 같은 값을 반복해서 읽는다. 그래서 `(3,1)`과 `(1,4)`를 더해 `(3,4)`를 만들어도 입력 쪽 추가 메모리는 거의 들지 않는다. 물론 연산 결과 배열 자체는 새로 만들어진다."}],"code":{"c":"import numpy as np\n\na = np.ones((3, 1))\nb = np.ones((1, 4))\nprint((a + b).shape)   # (3, 4)\n\nc = np.ones((5, 4))\nd = np.ones((4,))\nprint((c + d).shape)   # (5, 4)\n\ntry:\n    np.ones((3,)) + np.ones((4,))\nexcept ValueError as e:\n    print('ValueError:', e)","cap":"(3,1)과 (1,4)는 각 축에 1이 있어 서로 늘어나 (3,4)가 되고, (3,)와 (4,)는 호환되지 않아 ValueError다."},"key":["shape 비교는 뒤(오른쪽) 축부터 시작한다.","차원 수가 모자라면 shape 앞(왼쪽)에 1을 채운다.","각 축은 크기가 같거나 한쪽이 1이어야 하고, 아니면 ValueError다.","브로드캐스팅은 stride 0을 이용하므로 입력 데이터를 복제하지 않는다."]}},{"t":"shape 계산 훈련","q":[{"t":"input","k":"행렬+벡터","q":"shape (5,4) 배열과 shape (4,) 배열을 더하면 결과 shape는? (예: (2, 5) 형태로 답)","ex":"(4,)는 (1,4)로 확장된 뒤 뒤에서부터 4 vs 4, 5 vs 1로 비교된다. 마지막 축이 일치하고 앞쪽 1이 5로 늘어나 결과는 (5, 4)다. 행마다 같은 벡터를 더하는 전형적인 패턴이다.","code":"import numpy as np\nc = np.ones((5, 4))\nd = np.ones((4,))\nprint((c + d).shape)","a":["(5, 4)","(5,4)","5, 4","5,4"]},{"t":"choice","k":"3차원","q":"shape (2,3,4) 배열과 (3,1) 배열을 더하면 결과 shape는?","ex":"(3,1)은 앞에 1이 채워져 (1,3,1)이 된다. 뒤에서부터 1 vs 4는 1이 늘어나고, 3 vs 3은 일치, 1 vs 2는 1이 늘어나 결과는 (2,3,4)다.","o":["(2, 3, 1)","(2, 3, 4)","(3, 4)","ValueError"],"a":1},{"t":"choice","k":"4차원","q":"shape (8,1,6,1)과 (7,1,5)를 더하면 결과 shape는?","ex":"(7,1,5)는 (1,7,1,5)로 확장된다. 뒤에서부터 1 vs 5 → 5, 6 vs 1 → 6, 1 vs 7 → 7, 8 vs 1 → 8이 되어 (8,7,6,5)다. 양쪽이 번갈아 늘어나는 대표적인 예다.","o":["(8, 7, 6, 5)","(8, 1, 6, 1)","(7, 1, 5)","ValueError"],"a":0},{"t":"input","k":"열벡터+행벡터","q":"shape (4,1) 배열과 (3,) 배열을 더하면 결과 shape는? (예: (2, 5) 형태로 답)","ex":"(3,)는 (1,3)이 되고 (4,1)과 뒤에서부터 비교하면 1 vs 3 → 3, 4 vs 1 → 4가 된다. 결과는 (4, 3)으로, 열벡터와 행벡터의 조합이 격자를 만드는 패턴이다.","code":"import numpy as np\nprint((np.ones((4, 1)) + np.ones((3,))).shape)","a":["(4, 3)","(4,3)","4, 3","4,3"]},{"t":"choice","k":"차원 불일치","q":"shape (2,3) 배열과 (2,3,4) 배열을 더하면?","ex":"(2,3)은 앞에 1이 채워져 (1,2,3)이 된다. 뒤에서부터 3 vs 4를 비교하는 순간 둘 다 1이 아니고 다르므로 ValueError다. 앞쪽 축이 (2,3)으로 같아 보여도 비교는 뒤에서 시작한다는 점이 핵심이다.","o":["(2, 3, 4)","(2, 3)","ValueError","(2, 2, 3)"],"a":2}],"th":{"sum":"브로드캐스팅은 shape가 다른 배열끼리 연산할 때 NumPy가 자동으로 축을 맞춰 주는 규칙이다. 두 shape를 뒤에서부터 축 단위로 비교해, 같거나 한쪽이 1이면 늘려서 맞춘다.","body":[{"h":"뒤(오른쪽)에서부터 비교한다","t":"브로드캐스팅은 두 배열의 shape를 **뒤(오른쪽)에서부터** 축 단위로 하나씩 비교한다. 앞(왼쪽)부터 비교하는 것이 아니라는 점이 가장 흔한 오해다. 예를 들어 `(5,4)`와 `(4,)`를 비교하면 마지막 축끼리 4와 4가 만나 호환되고 결과는 `(5,4)`가 된다."},{"h":"차원 수가 다르면 앞에 1을 채운다","t":"두 배열의 차원 개수가 다르면 부족한 쪽 shape의 **앞(왼쪽)**에 1을 채워 길이를 맞춘 뒤 비교를 시작한다. `(2,3,4)`와 `(3,1)`이면 뒤쪽이 `(1,3,1)`로 확장된다. 그 다음 축별로 4 vs 1, 3 vs 3, 2 vs 1을 비교해 결과는 `(2,3,4)`가 된다."},{"h":"각 축은 같거나 1이어야 한다","t":"축별 크기가 서로 같으면 그대로 두고, 한쪽이 1이면 상대 크기만큼 늘린다(stretch). 둘 다 1이 아니면서 크기가 다르면 ValueError가 난다. `(3,)`와 `(4,)`는 3과 4가 만나 어느 쪽도 1이 아니므로 에러이고, `(3,1)`과 `(1,4)`는 양쪽 모두 1이 있어 `(3,4)`로 늘어난다."},{"h":"데이터는 실제로 복제되지 않는다","t":"브로드캐스팅은 작은 배열을 물리적으로 복제하지 않고 해당 축의 stride를 0으로 두어 같은 값을 반복해서 읽는다. 그래서 `(3,1)`과 `(1,4)`를 더해 `(3,4)`를 만들어도 입력 쪽 추가 메모리는 거의 들지 않는다. 물론 연산 결과 배열 자체는 새로 만들어진다."}],"code":{"c":"import numpy as np\n\na = np.ones((3, 1))\nb = np.ones((1, 4))\nprint((a + b).shape)   # (3, 4)\n\nc = np.ones((5, 4))\nd = np.ones((4,))\nprint((c + d).shape)   # (5, 4)\n\ntry:\n    np.ones((3,)) + np.ones((4,))\nexcept ValueError as e:\n    print('ValueError:', e)","cap":"(3,1)과 (1,4)는 각 축에 1이 있어 서로 늘어나 (3,4)가 되고, (3,)와 (4,)는 호환되지 않아 ValueError다."},"key":["shape 비교는 뒤(오른쪽) 축부터 시작한다.","차원 수가 모자라면 shape 앞(왼쪽)에 1을 채운다.","각 축은 크기가 같거나 한쪽이 1이어야 하고, 아니면 ValueError다.","브로드캐스팅은 stride 0을 이용하므로 입력 데이터를 복제하지 않는다."]}},{"t":"에러 잡고 실전 적용하기","q":[{"t":"choice","k":"에러 해결","q":"길이 3 벡터와 길이 4 벡터로 (3,4) 격자를 만들고 싶다. 올바른 방법은?","ex":"[:, None] 또는 np.newaxis로 축을 하나 추가하면 (3,)이 (3,1)이 되어 (4,)와 브로드캐스팅된다. 결과는 (3,4)다. reshape로 원소 수를 억지로 맞추는 것은 의미가 다른 연산이다.","o":["np.array로 다시 만들면 자동으로 해결된다","한쪽을 [:, None]으로 (3,1)로 만들어 (1,4)와 만나게 한다","두 배열을 모두 길이 12로 reshape한다","브로드캐스팅으로는 불가능하고 파이썬 for문을 써야 한다"],"a":1},{"t":"input","k":"외적 패턴","q":"아래 코드의 출력 shape는? (예: (2, 5) 형태로 답)","ex":"v[:, None]은 (3,1), w[None, :]은 (1,4)가 된다. 뒤에서부터 1 vs 4, 3 vs 1로 양쪽이 늘어나 (3,4)가 나온다. 외적(outer product)을 브로드캐스팅으로 표현하는 관용구다.","code":"import numpy as np\nv = np.arange(1, 4)          # shape (3,)\nw = np.arange(1, 5)          # shape (4,)\nprint((v[:, None] * w[None, :]).shape)","a":["(3, 4)","(3,4)","3, 4","3,4"]},{"t":"choice","k":"양방향 확장","q":"shape (1,5) 배열과 (5,1) 배열을 더하면 결과 shape는?","ex":"뒤에서부터 5 vs 1을 비교하면 1이 5로 늘어나고, 1 vs 5를 비교하면 역시 1이 5로 늘어난다. 두 배열이 서로 다른 축에서 확장되어 (5,5)가 된다. 결과가 입력보다 훨씬 커지는 경우라 실수로 만들면 메모리 폭발의 원인이 된다.","o":["(5,)","(1, 5)","(5, 5)","ValueError"],"a":2},{"t":"choice","k":"평균 빼기","q":"아래 코드에서 출력되는 shape는?","ex":"X.mean(axis=0)은 열별 평균이라 shape가 (3,)이다. (2,3)과 (3,)를 뒤에서부터 비교하면 3 vs 3으로 일치하고 앞 축은 1이 2로 늘어나 (2,3)이 된다. 열 단위 중심화(centering)의 표준 패턴이다.","code":"import numpy as np\nX = np.array([[1., 2., 3.], [4., 5., 6.]])   # shape (2, 3)\nprint((X - X.mean(axis=0)).shape)","o":["(2, 3)","(3,)","(2, 1)","ValueError"],"a":0},{"t":"input","k":"길이 1 벡터","q":"shape (6,) 배열과 (1,) 배열을 더하면 결과 shape는? (예: (7,) 형태로 답)","ex":"뒤에서부터 6 vs 1을 비교하면 한쪽이 1이므로 6으로 늘어난다. 결과 shape는 (6,)이며, 길이 1 배열은 사실상 스칼라처럼 모든 원소에 적용된다.","a":["(6,)","(6, )","6,","6"]}],"th":{"sum":"브로드캐스팅은 shape가 다른 배열끼리 연산할 때 NumPy가 자동으로 축을 맞춰 주는 규칙이다. 두 shape를 뒤에서부터 축 단위로 비교해, 같거나 한쪽이 1이면 늘려서 맞춘다.","body":[{"h":"뒤(오른쪽)에서부터 비교한다","t":"브로드캐스팅은 두 배열의 shape를 **뒤(오른쪽)에서부터** 축 단위로 하나씩 비교한다. 앞(왼쪽)부터 비교하는 것이 아니라는 점이 가장 흔한 오해다. 예를 들어 `(5,4)`와 `(4,)`를 비교하면 마지막 축끼리 4와 4가 만나 호환되고 결과는 `(5,4)`가 된다."},{"h":"차원 수가 다르면 앞에 1을 채운다","t":"두 배열의 차원 개수가 다르면 부족한 쪽 shape의 **앞(왼쪽)**에 1을 채워 길이를 맞춘 뒤 비교를 시작한다. `(2,3,4)`와 `(3,1)`이면 뒤쪽이 `(1,3,1)`로 확장된다. 그 다음 축별로 4 vs 1, 3 vs 3, 2 vs 1을 비교해 결과는 `(2,3,4)`가 된다."},{"h":"각 축은 같거나 1이어야 한다","t":"축별 크기가 서로 같으면 그대로 두고, 한쪽이 1이면 상대 크기만큼 늘린다(stretch). 둘 다 1이 아니면서 크기가 다르면 ValueError가 난다. `(3,)`와 `(4,)`는 3과 4가 만나 어느 쪽도 1이 아니므로 에러이고, `(3,1)`과 `(1,4)`는 양쪽 모두 1이 있어 `(3,4)`로 늘어난다."},{"h":"데이터는 실제로 복제되지 않는다","t":"브로드캐스팅은 작은 배열을 물리적으로 복제하지 않고 해당 축의 stride를 0으로 두어 같은 값을 반복해서 읽는다. 그래서 `(3,1)`과 `(1,4)`를 더해 `(3,4)`를 만들어도 입력 쪽 추가 메모리는 거의 들지 않는다. 물론 연산 결과 배열 자체는 새로 만들어진다."}],"code":{"c":"import numpy as np\n\na = np.ones((3, 1))\nb = np.ones((1, 4))\nprint((a + b).shape)   # (3, 4)\n\nc = np.ones((5, 4))\nd = np.ones((4,))\nprint((c + d).shape)   # (5, 4)\n\ntry:\n    np.ones((3,)) + np.ones((4,))\nexcept ValueError as e:\n    print('ValueError:', e)","cap":"(3,1)과 (1,4)는 각 축에 1이 있어 서로 늘어나 (3,4)가 되고, (3,)와 (4,)는 호환되지 않아 ValueError다."},"key":["shape 비교는 뒤(오른쪽) 축부터 시작한다.","차원 수가 모자라면 shape 앞(왼쪽)에 1을 채운다.","각 축은 크기가 같거나 한쪽이 1이어야 하고, 아니면 ValueError다.","브로드캐스팅은 stride 0을 이용하므로 입력 데이터를 복제하지 않는다."]}}]},{"t":"뷰(view) vs 복사(copy) — 기본 슬라이싱의 함정","l":[{"t":"슬라이싱은 뷰다","q":[{"t":"choice","k":"뷰 수정","q":"아래 코드를 실행하면 a[2]의 값은?","ex":"a[2:5]는 기본 슬라이싱이라 복사가 아닌 뷰다. b[0]은 a[2]와 같은 메모리 위치를 가리키므로 99를 쓰면 원본 a도 함께 바뀐다. 원본을 지키고 싶었다면 a[2:5].copy()를 써야 했다.","code":"import numpy as np\na = np.arange(10)\nb = a[2:5]\nb[0] = 99\nprint(a[2])","o":["2","0","99","IndexError가 발생한다"],"a":2},{"t":"input","k":"분리 방법","q":"슬라이싱 결과를 원본과 완전히 분리된 새 배열로 만들려면 어떤 메서드를 호출해야 하는가? (메서드 이름만)","ex":".copy()는 데이터를 새 메모리에 복제해 원본과 완전히 독립된 배열을 만든다. 이후 어느 쪽을 수정해도 서로 영향을 주지 않으며, 그 결과의 .base는 None이다.","a":["copy","copy()",".copy()","a.copy()"]},{"t":"choice","k":"확인 속성","q":"어떤 배열이 뷰인지 복사본인지 확인할 때 보는 속성은?","ex":"arr.base는 뷰일 때 데이터를 소유한 원본 배열을 가리키고, 독립된 복사본이면 None이다. arr.is_view나 arr.flags.copy 같은 속성은 존재하지 않는다.","o":["arr.base","arr.flags.copy","arr.is_view","arr.dtype"],"a":0}],"th":{"sum":"NumPy의 기본 슬라이싱은 데이터를 복사하지 않고 원본 메모리를 들여다보는 뷰를 돌려준다. 뷰를 수정하면 원본도 함께 바뀌므로 언제 뷰이고 언제 복사인지 반드시 구분해야 한다.","body":[{"h":"기본 슬라이싱은 뷰다","t":"`a[2:5]`, `a[:, 1]`, `a[::2]` 같은 기본(basic) 슬라이싱은 새 메모리를 만들지 않고 원본 버퍼를 다른 offset과 stride로 바라보는 **뷰**를 반환한다. 뷰의 원소를 바꾸면 원본 배열의 값도 같이 바뀐다. 파이썬 리스트 슬라이싱이 복사본을 주는 것과 정반대라 가장 자주 사고가 나는 지점이다."},{"h":"팬시 인덱싱과 불리언 마스크는 복사다","t":"정수 배열로 인덱싱하는 팬시 인덱싱 `a[[0,2,4]]`와 불리언 마스크 인덱싱 `a[a > 3]`은 **복사본**을 반환한다. 선택된 원소들이 원본에서 일정한 간격으로 놓여 있다는 보장이 없어 offset과 stride만으로는 표현할 수 없기 때문이다. 그래서 복사본을 수정해도 원본은 그대로다."},{"h":"arr.base로 확인한다","t":"`arr.base`를 보면 뷰인지 알 수 있다. 뷰라면 데이터를 소유한 원본 배열을 가리키고, 독립된 복사본이라면 `None`이다. 원본과 확실히 분리하고 싶다면 `.copy()`를 명시적으로 호출해 데이터를 새로 할당해야 한다."},{"h":"reshape · ravel · T의 미묘한 차이","t":"`.T`(transpose)는 stride 순서만 바꾸므로 항상 뷰다. `reshape`는 가능하면 뷰를 반환하지만 메모리 연속성이 맞지 않으면 복사할 수 있다. `ravel()`은 가능하면 뷰를 주고, `flatten()`은 **항상** 복사를 반환한다는 점이 둘의 결정적 차이다."},{"h":"뷰는 원본 메모리를 붙잡는다","t":"1GB 배열에서 10개 원소만 슬라이싱해 오래 들고 있으면, 그 뷰가 원본 버퍼를 참조하고 있어 1GB가 통째로 메모리에서 해제되지 않는다. 작은 조각만 장기 보관할 때는 `.copy()`로 떼어 내는 편이 낫다. 반대로 큰 데이터를 잠깐 훑어볼 때는 뷰가 압도적으로 효율적이다."}],"code":{"c":"import numpy as np\n\na = np.arange(10)\nb = a[2:5]           # 기본 슬라이싱 -> 뷰\nb[0] = 99\nprint(a)             # [ 0  1 99  3  4  5  6  7  8  9]\nprint(b.base is a)   # True\n\nc = a[[2, 3, 4]]     # 팬시 인덱싱 -> 복사\nc[0] = -1\nprint(a[2], c.base)  # 99 None","cap":"뷰를 고치면 원본이 바뀌고, 팬시 인덱싱이 만든 복사본을 고쳐도 원본은 그대로다."},"key":["기본 슬라이싱은 뷰이므로 수정하면 원본도 바뀐다.","팬시 인덱싱과 불리언 마스크는 복사본을 돌려준다.","arr.base가 None이면 복사본, 원본 배열을 가리키면 뷰다.","ravel()은 가능하면 뷰, flatten()은 항상 복사다."]}},{"t":"복사를 반환하는 인덱싱","q":[{"t":"choice","k":"마스크 인덱싱","q":"아래 코드를 실행하면 a[0]의 값은?","ex":"불리언 마스크 인덱싱은 복사본을 돌려주므로 m을 수정해도 a는 그대로 [0 1 2 3 4 5]다. 마스크로 고른 원소를 원본에 반영하려면 a[a % 2 == 0] = 99처럼 좌변에 직접 대입해야 한다.","code":"import numpy as np\na = np.arange(6)\nm = a[a % 2 == 0]\nm[0] = 99\nprint(a[0])","o":["0","99","2","ValueError가 발생한다"],"a":0},{"t":"input","k":"복사본의 base","q":"팬시 인덱싱 결과 c = a[[0, 2, 4]] 에서 c.base 를 출력하면 무엇이 나오는가?","ex":"복사본은 자기 데이터를 직접 소유하므로 base가 None이다. 만약 base가 어떤 배열을 가리킨다면 그것은 뷰라는 뜻이다.","a":["None","none","널","null"]},{"t":"choice","k":"전치","q":"a.T (transpose)에 대한 설명으로 옳은 것은?","ex":"전치는 데이터를 옮기지 않고 축의 stride 순서만 뒤바꾸므로 뷰다. 따라서 a.T의 원소를 수정하면 a도 함께 바뀐다. dtype이나 차원 수와는 무관하다.","o":["항상 데이터를 복사한 새 배열이다","1차원 배열에서만 뷰가 된다","stride 순서만 바꾸는 뷰다","float 배열일 때만 뷰가 된다"],"a":2},{"t":"input","k":"전치 뷰 수정","q":"아래 코드의 출력값은?","ex":"b는 a의 전치 뷰이므로 b[0, 1]은 a[1, 0]과 같은 메모리 위치다. 따라서 99를 쓰면 a[1, 0]도 99가 된다. 전치 결과를 안심하고 수정하면 안 되는 이유다.","code":"import numpy as np\na = np.array([[1, 2], [3, 4]])\nb = a.T\nb[0, 1] = 99\nprint(a[1, 0])","a":["99"]}],"th":{"sum":"NumPy의 기본 슬라이싱은 데이터를 복사하지 않고 원본 메모리를 들여다보는 뷰를 돌려준다. 뷰를 수정하면 원본도 함께 바뀌므로 언제 뷰이고 언제 복사인지 반드시 구분해야 한다.","body":[{"h":"기본 슬라이싱은 뷰다","t":"`a[2:5]`, `a[:, 1]`, `a[::2]` 같은 기본(basic) 슬라이싱은 새 메모리를 만들지 않고 원본 버퍼를 다른 offset과 stride로 바라보는 **뷰**를 반환한다. 뷰의 원소를 바꾸면 원본 배열의 값도 같이 바뀐다. 파이썬 리스트 슬라이싱이 복사본을 주는 것과 정반대라 가장 자주 사고가 나는 지점이다."},{"h":"팬시 인덱싱과 불리언 마스크는 복사다","t":"정수 배열로 인덱싱하는 팬시 인덱싱 `a[[0,2,4]]`와 불리언 마스크 인덱싱 `a[a > 3]`은 **복사본**을 반환한다. 선택된 원소들이 원본에서 일정한 간격으로 놓여 있다는 보장이 없어 offset과 stride만으로는 표현할 수 없기 때문이다. 그래서 복사본을 수정해도 원본은 그대로다."},{"h":"arr.base로 확인한다","t":"`arr.base`를 보면 뷰인지 알 수 있다. 뷰라면 데이터를 소유한 원본 배열을 가리키고, 독립된 복사본이라면 `None`이다. 원본과 확실히 분리하고 싶다면 `.copy()`를 명시적으로 호출해 데이터를 새로 할당해야 한다."},{"h":"reshape · ravel · T의 미묘한 차이","t":"`.T`(transpose)는 stride 순서만 바꾸므로 항상 뷰다. `reshape`는 가능하면 뷰를 반환하지만 메모리 연속성이 맞지 않으면 복사할 수 있다. `ravel()`은 가능하면 뷰를 주고, `flatten()`은 **항상** 복사를 반환한다는 점이 둘의 결정적 차이다."},{"h":"뷰는 원본 메모리를 붙잡는다","t":"1GB 배열에서 10개 원소만 슬라이싱해 오래 들고 있으면, 그 뷰가 원본 버퍼를 참조하고 있어 1GB가 통째로 메모리에서 해제되지 않는다. 작은 조각만 장기 보관할 때는 `.copy()`로 떼어 내는 편이 낫다. 반대로 큰 데이터를 잠깐 훑어볼 때는 뷰가 압도적으로 효율적이다."}],"code":{"c":"import numpy as np\n\na = np.arange(10)\nb = a[2:5]           # 기본 슬라이싱 -> 뷰\nb[0] = 99\nprint(a)             # [ 0  1 99  3  4  5  6  7  8  9]\nprint(b.base is a)   # True\n\nc = a[[2, 3, 4]]     # 팬시 인덱싱 -> 복사\nc[0] = -1\nprint(a[2], c.base)  # 99 None","cap":"뷰를 고치면 원본이 바뀌고, 팬시 인덱싱이 만든 복사본을 고쳐도 원본은 그대로다."},"key":["기본 슬라이싱은 뷰이므로 수정하면 원본도 바뀐다.","팬시 인덱싱과 불리언 마스크는 복사본을 돌려준다.","arr.base가 None이면 복사본, 원본 배열을 가리키면 뷰다.","ravel()은 가능하면 뷰, flatten()은 항상 복사다."]}},{"t":"실전: 원본 오염 막기","q":[{"t":"choice","k":"인플레이스 연산","q":"아래 코드의 출력은?","ex":"y는 x의 뷰이고 +=는 인플레이스 연산이라 뷰가 가리키는 메모리를 직접 수정한다. 결과적으로 x의 1~3번 원소만 10씩 늘어나 [0 11 12 13 4]가 된다. y = y + 10이었다면 새 배열이 생겨 x는 그대로였다.","code":"import numpy as np\nx = np.arange(5)\ny = x[1:4]\ny += 10\nprint(x)","o":["[0 1 2 3 4]","[10 11 12 13 14]","[ 0 11 12 13  4]","ValueError가 발생한다"],"a":2},{"t":"choice","k":"메모리 보관","q":"매우 큰 배열에서 작은 부분만 슬라이싱해 오랫동안 보관할 때 주의할 점은?","ex":"뷰가 살아 있는 동안에는 원본 버퍼도 함께 살아 있어야 하므로 큰 메모리가 계속 점유된다. 작은 조각만 오래 들고 있을 계획이면 .copy()로 떼어 내는 편이 낫다.","o":["뷰는 원본이 바뀌어도 값이 갱신되지 않는다","뷰가 원본 버퍼를 참조하므로 원본 전체가 메모리에서 해제되지 않는다","뷰는 dtype이 자동으로 float64로 바뀐다","뷰는 읽기 전용이라 값을 수정할 수 없다"],"a":1},{"t":"input","k":"2차원 슬라이스","q":"아래 코드의 출력값은?","ex":"a[:, 1:]도 기본 슬라이싱이라 뷰다. b[0, 0]은 a[0, 1]과 같은 위치이므로 0을 쓰면 원본이 바뀐다. 2차원에서도 규칙은 똑같이 적용된다.","code":"import numpy as np\na = np.array([[1, 2, 3], [4, 5, 6]])\nb = a[:, 1:]\nb[0, 0] = 0\nprint(a[0, 1])","a":["0"]},{"t":"choice","k":"항상 독립","q":"다음 중 언제나 원본과 독립된 배열을 돌려주는 것은?","ex":"flatten()은 조건과 무관하게 항상 새 메모리에 복사한다. a[::2]와 a.T는 뷰이고, a.reshape(-1)은 상황에 따라 뷰일 수도 복사일 수도 있어 보장되지 않는다.","o":["a[::2]","a.reshape(-1)","a.T","a.flatten()"],"a":3},{"t":"choice","k":"base 확인","q":"a = np.array([1, 2, 3, 4, 5]) 로 만든 뒤 b = a[2:5] 를 실행했다. b.base is a 의 값은?","ex":"a는 직접 만든 배열이라 데이터를 소유하고(a.base는 None), b는 그 슬라이스 뷰라 b.base가 a를 가리킨다. 따라서 b.base is a는 True다. 반면 a 자체가 이미 다른 배열의 뷰였다면 b.base가 더 상위 원본을 가리킬 수 있어 결과가 달라진다.","o":["True","False","None","AttributeError가 발생한다"],"a":0}],"th":{"sum":"NumPy의 기본 슬라이싱은 데이터를 복사하지 않고 원본 메모리를 들여다보는 뷰를 돌려준다. 뷰를 수정하면 원본도 함께 바뀌므로 언제 뷰이고 언제 복사인지 반드시 구분해야 한다.","body":[{"h":"기본 슬라이싱은 뷰다","t":"`a[2:5]`, `a[:, 1]`, `a[::2]` 같은 기본(basic) 슬라이싱은 새 메모리를 만들지 않고 원본 버퍼를 다른 offset과 stride로 바라보는 **뷰**를 반환한다. 뷰의 원소를 바꾸면 원본 배열의 값도 같이 바뀐다. 파이썬 리스트 슬라이싱이 복사본을 주는 것과 정반대라 가장 자주 사고가 나는 지점이다."},{"h":"팬시 인덱싱과 불리언 마스크는 복사다","t":"정수 배열로 인덱싱하는 팬시 인덱싱 `a[[0,2,4]]`와 불리언 마스크 인덱싱 `a[a > 3]`은 **복사본**을 반환한다. 선택된 원소들이 원본에서 일정한 간격으로 놓여 있다는 보장이 없어 offset과 stride만으로는 표현할 수 없기 때문이다. 그래서 복사본을 수정해도 원본은 그대로다."},{"h":"arr.base로 확인한다","t":"`arr.base`를 보면 뷰인지 알 수 있다. 뷰라면 데이터를 소유한 원본 배열을 가리키고, 독립된 복사본이라면 `None`이다. 원본과 확실히 분리하고 싶다면 `.copy()`를 명시적으로 호출해 데이터를 새로 할당해야 한다."},{"h":"reshape · ravel · T의 미묘한 차이","t":"`.T`(transpose)는 stride 순서만 바꾸므로 항상 뷰다. `reshape`는 가능하면 뷰를 반환하지만 메모리 연속성이 맞지 않으면 복사할 수 있다. `ravel()`은 가능하면 뷰를 주고, `flatten()`은 **항상** 복사를 반환한다는 점이 둘의 결정적 차이다."},{"h":"뷰는 원본 메모리를 붙잡는다","t":"1GB 배열에서 10개 원소만 슬라이싱해 오래 들고 있으면, 그 뷰가 원본 버퍼를 참조하고 있어 1GB가 통째로 메모리에서 해제되지 않는다. 작은 조각만 장기 보관할 때는 `.copy()`로 떼어 내는 편이 낫다. 반대로 큰 데이터를 잠깐 훑어볼 때는 뷰가 압도적으로 효율적이다."}],"code":{"c":"import numpy as np\n\na = np.arange(10)\nb = a[2:5]           # 기본 슬라이싱 -> 뷰\nb[0] = 99\nprint(a)             # [ 0  1 99  3  4  5  6  7  8  9]\nprint(b.base is a)   # True\n\nc = a[[2, 3, 4]]     # 팬시 인덱싱 -> 복사\nc[0] = -1\nprint(a[2], c.base)  # 99 None","cap":"뷰를 고치면 원본이 바뀌고, 팬시 인덱싱이 만든 복사본을 고쳐도 원본은 그대로다."},"key":["기본 슬라이싱은 뷰이므로 수정하면 원본도 바뀐다.","팬시 인덱싱과 불리언 마스크는 복사본을 돌려준다.","arr.base가 None이면 복사본, 원본 배열을 가리키면 뷰다.","ravel()은 가능하면 뷰, flatten()은 항상 복사다."]}}]},{"t":"축(axis) 연산과 차원 축소/유지(keepdims) 중급","l":[{"t":"axis 방향 이해하기","q":[{"t":"choice","k":"axis=0 shape","q":"shape가 (3,4)인 배열 X에 대해 X.sum(axis=0)의 결과 shape는?","ex":"axis=0을 지정하면 0번 축(길이 3)이 사라지고 (4,)만 남는다. 즉 열마다 하나씩, 총 4개의 값이 나온다. (1,4)는 keepdims=True를 줬을 때의 결과다.","o":["(3,)","(4,)","(3, 4)","(1, 4)"],"a":1},{"t":"choice","k":"axis=0 의미","q":"2차원 배열에서 axis=0으로 sum을 하면 의미상 무엇을 계산하는가?","ex":"axis=0은 행을 따라 아래로 훑으며 뭉개는 것이므로 결과는 열마다 하나씩 나온다. axis=0이 행별 결과를 준다는 것은 대표적인 오개념이다. 행별 결과가 필요하면 axis=1을 써야 한다.","o":["행별 결과를 준다 (각 행마다 하나의 값)","결과 shape가 항상 (1, n)이 된다","행 방향으로 축소되어 열별 결과를 준다","0번 축만 남기고 나머지 축을 모두 없앤다"],"a":2},{"t":"input","k":"axis=1 shape","q":"아래 코드의 출력값은? (예: (2, 5) 형태로 답)","ex":"axis=1을 주면 1번 축(길이 4)이 사라지고 (3,)이 남는다. 실제 값은 [6 22 38]으로 각 행의 합이다.","code":"import numpy as np\nX = np.arange(12).reshape(3, 4)\nprint(X.sum(axis=1).shape)","a":["(3,)","(3, )","3,","3"]},{"t":"choice","k":"3차원 축소","q":"w = np.arange(24).reshape(2, 3, 4) 일 때 w.sum(axis=1).shape 는?","ex":"axis=1은 길이 3인 축이므로 그 축이 사라지고 (2, 4)가 남는다. 3차원에서도 규칙은 같아서 지정한 축의 자리만 shape에서 빠진다.","o":["(2, 4)","(3, 4)","(2, 3)","(2, 3, 4)"],"a":0},{"t":"choice","k":"음수 축","q":"axis=-1은 어떤 축을 가리키는가?","ex":"파이썬의 음수 인덱스와 동일하게 -1은 마지막 축이다. (3,4) 배열이라면 axis=-1은 axis=1과 같고, 차원 수를 모르는 코드에서 마지막 축을 안전하게 가리킬 때 유용하다.","o":["첫 번째 축","마지막 축","존재하지 않는 축이라 에러","축소하지 않음을 의미"],"a":1}],"th":{"sum":"축소 연산에서 axis는 사라지는 축을 가리킨다. axis=0이면 행 방향으로 뭉개져 열별 결과가, axis=1이면 열 방향으로 뭉개져 행별 결과가 나오며, keepdims=True로 축소된 축을 크기 1로 남길 수 있다.","body":[{"h":"axis는 사라지는 축이다","t":"`sum`, `mean` 같은 축소(reduction) 연산에서 `axis`로 지정한 축이 결과에서 **없어진다**. shape가 `(3,4)`인 배열에 `sum(axis=0)`을 하면 0번 축(행 방향)이 사라져 결과 shape는 `(4,)`, 즉 열별 합이다. 반대로 `sum(axis=1)`은 1번 축이 사라져 `(3,)`, 곧 행별 합이 된다."},{"h":"axis=None은 전체 스칼라","t":"axis를 주지 않으면 기본값이 `None`이라 모든 축을 축소해 스칼라 하나가 나온다. 여러 축을 튜플로 줄 수도 있어서 `(2,3,4)` 배열에 `sum(axis=(0,2))`를 하면 `(3,)`만 남는다. 음수 축도 사용할 수 있고 `axis=-1`은 마지막 축을 뜻한다."},{"h":"keepdims=True로 차원 유지","t":"`keepdims=True`를 주면 축소된 축이 사라지지 않고 **크기 1로 남는다**. `(3,4)` 배열에 `sum(axis=1, keepdims=True)`를 하면 `(3,1)`이 되고, 이 값으로 원본을 나누면 브로드캐스팅이 그대로 맞아떨어져 행별 정규화가 깔끔하게 된다. 차원 수가 유지되므로 이어지는 연산의 shape가 예측 가능해진다."},{"h":"keepdims 없이 나누면 에러","t":"`(3,4)`를 `sum(axis=1)`의 결과 `(3,)`으로 나누면 브로드캐스팅이 뒤에서부터 4와 3을 비교해 ValueError가 난다. `keepdims=True`를 주거나 `[:, None]`으로 `(3,1)`을 만들어야 한다. 축 연산과 브로드캐스팅 규칙이 정확히 맞물리는 지점이다."}],"code":{"c":"import numpy as np\n\nX = np.arange(12).reshape(3, 4)\nprint(X.sum(axis=0))                       # [12 15 18 21]  열별 합, shape (4,)\nprint(X.sum(axis=1))                       # [ 6 22 38]     행별 합, shape (3,)\nprint(X.sum(axis=1, keepdims=True).shape)  # (3, 1)\nprint(X.sum())                             # 66  전체 합\n\n# 행별 정규화: keepdims 덕분에 브로드캐스팅이 맞는다\nprint(X / X.sum(axis=1, keepdims=True))","cap":"axis로 지정한 축은 결과에서 사라지고, keepdims=True를 주면 크기 1로 남아 브로드캐스팅에 바로 쓸 수 있다."},"key":["axis=0은 행 방향으로 축소되어 열별 결과를 준다.","axis=1은 열 방향으로 축소되어 행별 결과를 준다.","axis를 생략하면 전체를 축소해 스칼라가 나온다.","keepdims=True는 축소된 축을 크기 1로 남겨 브로드캐스팅을 편하게 만든다."]}},{"t":"keepdims와 정규화","q":[{"t":"input","k":"keepdims shape","q":"shape (3,4) 배열에 sum(axis=1, keepdims=True)를 하면 결과 shape는? (예: (2, 5) 형태로 답)","ex":"keepdims=True를 주면 축소된 1번 축이 사라지지 않고 크기 1로 남는다. 따라서 (3,) 대신 (3, 1)이 되어 원래 2차원이 유지된다.","code":"import numpy as np\nX = np.arange(12).reshape(3, 4)\nprint(X.sum(axis=1, keepdims=True).shape)","a":["(3, 1)","(3,1)","3, 1","3,1"]},{"t":"choice","k":"keepdims 대안","q":"X.sum(axis=1, keepdims=True) 와 같은 shape를 만드는 표현은?","ex":"(3,)에 [:, None]을 적용하면 뒤에 축이 추가되어 (3,1)이 된다. [None, :]나 reshape(1,-1)은 (1,3)이 되어 방향이 반대이고, 1차원 배열의 .T는 아무 변화가 없다.","o":["X.sum(axis=1)[:, None]","X.sum(axis=1)[None, :]","X.sum(axis=1).T","X.sum(axis=1).reshape(1, -1)"],"a":0},{"t":"choice","k":"3차원 keepdims","q":"w = np.arange(24).reshape(2, 3, 4) 일 때 w.sum(axis=2, keepdims=True).shape 는?","ex":"axis=2가 축소되지만 keepdims=True 덕분에 그 자리가 1로 남아 (2, 3, 1)이 된다. keepdims 없이 하면 (2, 3)이다.","o":["(2, 3)","(2, 1, 4)","(2, 3, 1)","(2, 3, 4)"],"a":2}],"th":{"sum":"축소 연산에서 axis는 사라지는 축을 가리킨다. axis=0이면 행 방향으로 뭉개져 열별 결과가, axis=1이면 열 방향으로 뭉개져 행별 결과가 나오며, keepdims=True로 축소된 축을 크기 1로 남길 수 있다.","body":[{"h":"axis는 사라지는 축이다","t":"`sum`, `mean` 같은 축소(reduction) 연산에서 `axis`로 지정한 축이 결과에서 **없어진다**. shape가 `(3,4)`인 배열에 `sum(axis=0)`을 하면 0번 축(행 방향)이 사라져 결과 shape는 `(4,)`, 즉 열별 합이다. 반대로 `sum(axis=1)`은 1번 축이 사라져 `(3,)`, 곧 행별 합이 된다."},{"h":"axis=None은 전체 스칼라","t":"axis를 주지 않으면 기본값이 `None`이라 모든 축을 축소해 스칼라 하나가 나온다. 여러 축을 튜플로 줄 수도 있어서 `(2,3,4)` 배열에 `sum(axis=(0,2))`를 하면 `(3,)`만 남는다. 음수 축도 사용할 수 있고 `axis=-1`은 마지막 축을 뜻한다."},{"h":"keepdims=True로 차원 유지","t":"`keepdims=True`를 주면 축소된 축이 사라지지 않고 **크기 1로 남는다**. `(3,4)` 배열에 `sum(axis=1, keepdims=True)`를 하면 `(3,1)`이 되고, 이 값으로 원본을 나누면 브로드캐스팅이 그대로 맞아떨어져 행별 정규화가 깔끔하게 된다. 차원 수가 유지되므로 이어지는 연산의 shape가 예측 가능해진다."},{"h":"keepdims 없이 나누면 에러","t":"`(3,4)`를 `sum(axis=1)`의 결과 `(3,)`으로 나누면 브로드캐스팅이 뒤에서부터 4와 3을 비교해 ValueError가 난다. `keepdims=True`를 주거나 `[:, None]`으로 `(3,1)`을 만들어야 한다. 축 연산과 브로드캐스팅 규칙이 정확히 맞물리는 지점이다."}],"code":{"c":"import numpy as np\n\nX = np.arange(12).reshape(3, 4)\nprint(X.sum(axis=0))                       # [12 15 18 21]  열별 합, shape (4,)\nprint(X.sum(axis=1))                       # [ 6 22 38]     행별 합, shape (3,)\nprint(X.sum(axis=1, keepdims=True).shape)  # (3, 1)\nprint(X.sum())                             # 66  전체 합\n\n# 행별 정규화: keepdims 덕분에 브로드캐스팅이 맞는다\nprint(X / X.sum(axis=1, keepdims=True))","cap":"axis로 지정한 축은 결과에서 사라지고, keepdims=True를 주면 크기 1로 남아 브로드캐스팅에 바로 쓸 수 있다."},"key":["axis=0은 행 방향으로 축소되어 열별 결과를 준다.","axis=1은 열 방향으로 축소되어 행별 결과를 준다.","axis를 생략하면 전체를 축소해 스칼라가 나온다.","keepdims=True는 축소된 축을 크기 1로 남겨 브로드캐스팅을 편하게 만든다."]}},{"t":"다축 연산과 실전 패턴","q":[{"t":"input","k":"여러 축 축소","q":"아래 코드의 출력값은? (예: (2, 5) 형태로 답)","ex":"axis에 튜플을 주면 지정한 축들이 모두 사라진다. 0번 축(2)과 2번 축(4)이 없어지고 1번 축(3)만 남아 (3,)이 된다.","code":"import numpy as np\nw = np.arange(24).reshape(2, 3, 4)\nprint(w.sum(axis=(0, 2)).shape)","a":["(3,)","(3, )","3,","3"]},{"t":"choice","k":"keepdims axis=0","q":"shape (3,4) 배열에 sum(axis=0, keepdims=True)를 하면 결과 shape는?","ex":"axis=0이 축소되지만 keepdims=True라서 그 자리가 1로 남아 (1, 4)가 된다. 이 값으로 원본을 나누면 열별 정규화가 된다. (3,1)은 axis=1에 keepdims를 준 결과다.","o":["(4,)","(1, 4)","(3, 1)","(3, 4)"],"a":1}],"th":{"sum":"축소 연산에서 axis는 사라지는 축을 가리킨다. axis=0이면 행 방향으로 뭉개져 열별 결과가, axis=1이면 열 방향으로 뭉개져 행별 결과가 나오며, keepdims=True로 축소된 축을 크기 1로 남길 수 있다.","body":[{"h":"axis는 사라지는 축이다","t":"`sum`, `mean` 같은 축소(reduction) 연산에서 `axis`로 지정한 축이 결과에서 **없어진다**. shape가 `(3,4)`인 배열에 `sum(axis=0)`을 하면 0번 축(행 방향)이 사라져 결과 shape는 `(4,)`, 즉 열별 합이다. 반대로 `sum(axis=1)`은 1번 축이 사라져 `(3,)`, 곧 행별 합이 된다."},{"h":"axis=None은 전체 스칼라","t":"axis를 주지 않으면 기본값이 `None`이라 모든 축을 축소해 스칼라 하나가 나온다. 여러 축을 튜플로 줄 수도 있어서 `(2,3,4)` 배열에 `sum(axis=(0,2))`를 하면 `(3,)`만 남는다. 음수 축도 사용할 수 있고 `axis=-1`은 마지막 축을 뜻한다."},{"h":"keepdims=True로 차원 유지","t":"`keepdims=True`를 주면 축소된 축이 사라지지 않고 **크기 1로 남는다**. `(3,4)` 배열에 `sum(axis=1, keepdims=True)`를 하면 `(3,1)`이 되고, 이 값으로 원본을 나누면 브로드캐스팅이 그대로 맞아떨어져 행별 정규화가 깔끔하게 된다. 차원 수가 유지되므로 이어지는 연산의 shape가 예측 가능해진다."},{"h":"keepdims 없이 나누면 에러","t":"`(3,4)`를 `sum(axis=1)`의 결과 `(3,)`으로 나누면 브로드캐스팅이 뒤에서부터 4와 3을 비교해 ValueError가 난다. `keepdims=True`를 주거나 `[:, None]`으로 `(3,1)`을 만들어야 한다. 축 연산과 브로드캐스팅 규칙이 정확히 맞물리는 지점이다."}],"code":{"c":"import numpy as np\n\nX = np.arange(12).reshape(3, 4)\nprint(X.sum(axis=0))                       # [12 15 18 21]  열별 합, shape (4,)\nprint(X.sum(axis=1))                       # [ 6 22 38]     행별 합, shape (3,)\nprint(X.sum(axis=1, keepdims=True).shape)  # (3, 1)\nprint(X.sum())                             # 66  전체 합\n\n# 행별 정규화: keepdims 덕분에 브로드캐스팅이 맞는다\nprint(X / X.sum(axis=1, keepdims=True))","cap":"axis로 지정한 축은 결과에서 사라지고, keepdims=True를 주면 크기 1로 남아 브로드캐스팅에 바로 쓸 수 있다."},"key":["axis=0은 행 방향으로 축소되어 열별 결과를 준다.","axis=1은 열 방향으로 축소되어 행별 결과를 준다.","axis를 생략하면 전체를 축소해 스칼라가 나온다.","keepdims=True는 축소된 축을 크기 1로 남겨 브로드캐스팅을 편하게 만든다."]}}]},{"t":"벡터화·유니버설 함수(ufunc)와 난수·시드·재현성 심화","l":[{"t":"벡터화와 ufunc","q":[{"t":"input","k":"reduce","q":"아래 코드의 출력값은?","ex":"np.add.reduce는 배열을 add 연산으로 접어 하나의 값으로 만든다. 0+1+2+3+4 = 10이며 np.sum(np.arange(5))와 같은 결과다.","code":"import numpy as np\nprint(np.add.reduce(np.arange(5)))","a":["10"]},{"t":"choice","k":"연산자와 ufunc","q":"a * 2 같은 연산자 표현에 대한 설명으로 옳은 것은?","ex":"ndarray의 연산자 오버로딩은 대응하는 ufunc를 호출한다. 그래서 a * 2와 np.multiply(a, 2)는 사실상 같은 작업이다. 다만 a * 2는 새 배열을 만들고, 인플레이스로 하려면 a *= 2를 써야 한다.","o":["연산자는 순수 파이썬으로 처리되어 ufunc보다 느리다","연산자는 항상 원본을 인플레이스로 수정한다","연산자는 파이썬 리스트에만 쓸 수 있다","연산자도 내부적으로 ufunc(np.multiply 등)를 호출한다"],"a":3},{"t":"choice","k":"메모리 절약","q":"아주 큰 배열 a를 2배로 만들 때 추가 메모리를 가장 적게 쓰는 방법은?","ex":"out=a는 결과를 a 자체에 덮어써서 임시 배열을 만들지 않는다. a * 2와 np.multiply(a, 2)는 결과용 배열을 새로 할당한다. 리스트 컴프리헨션은 파이썬 객체를 원소 수만큼 만들어 가장 느리고 무겁다.","o":["a = a * 2","b = np.multiply(a, 2)","np.multiply(a, 2, out=a)","a = np.array([x * 2 for x in a])"],"a":2}],"th":{"sum":"ufunc는 원소별 연산을 C 루프로 돌려 파이썬 for문보다 훨씬 빠르고, out= 인자로 메모리 할당까지 줄일 수 있다. 난수는 np.random.default_rng(seed)로 만든 Generator를 쓰는 것이 재현성과 독립성을 함께 얻는 권장 방식이다.","body":[{"h":"ufunc와 벡터화","t":"`np.add`, `np.sqrt`, `np.exp` 같은 **유니버설 함수(ufunc)**는 배열 원소마다 동작하는 연산을 C 레벨 루프로 수행한다. 파이썬 `for` 루프는 원소마다 객체 생성과 인터프리터 오버헤드가 붙지만 ufunc에는 그 비용이 없어 훨씬 빠르다. `a + b`, `a * 2` 같은 연산자 표현도 내부적으로는 ufunc 호출로 이어진다."},{"h":"out=으로 할당 줄이기","t":"ufunc는 `out=` 인자를 받아 결과를 이미 존재하는 배열에 직접 기록한다. `np.multiply(a, 2, out=a)`처럼 쓰면 새 배열을 만들지 않아 큰 데이터에서 메모리와 시간을 아낄 수 있다. ufunc는 `reduce`, `accumulate` 같은 메서드도 제공해서 `np.add.reduce(x)`는 합, `np.add.accumulate(x)`는 누적합이 된다."},{"h":"Generator가 권장 방식이다","t":"재현 가능한 난수는 `rng = np.random.default_rng(42)`로 Generator를 만들어 `rng.random()`, `rng.integers()`를 호출하는 것이 권장 방식이다. 레거시인 `np.random.seed(42)` + `np.random.rand()`는 **전역 상태**를 공유해서, 다른 라이브러리가 같은 전역 난수를 소비하면 결과가 달라질 수 있다. Generator는 객체마다 상태를 따로 들고 있어 그런 간섭이 없다."},{"h":"같은 seed, 같은 순서라야 같은 값","t":"같은 seed로 만든 Generator는 같은 순서의 난수열을 재현한다. 하지만 **호출 순서나 횟수가 바뀌면 값도 달라진다**. seed를 한 번 정했다고 이후 모든 호출이 같은 값을 내는 것이 아니라, 정해진 수열을 앞에서부터 차례로 꺼내 쓰는 구조다."},{"h":"수치 함정: NaN과 정수 오버플로","t":"부동소수 `np.nan`은 자기 자신과도 같지 않아 `np.nan == np.nan`은 `False`다. 결측 판별은 반드시 `np.isnan()`을 써야 하고, 합계 등은 `np.nansum` 같은 nan 무시 함수를 쓴다. 정수 dtype은 범위를 넘으면 예외 없이 **wrap around** 되어 `np.int8`에서 100 + 100은 -56이 된다."}],"code":{"c":"import numpy as np\n\nrng = np.random.default_rng(42)\nprint(rng.random(3))    # [0.77395605 0.43887844 0.85859792]\n\nrng2 = np.random.default_rng(42)\nprint(rng2.random(3))   # 같은 seed -> 같은 수열 재현\n\nx = np.arange(5.0)\nout = np.empty(5)\nnp.multiply(x, 2, out=out)   # 새 배열 할당 없이 out에 기록\nprint(out)              # [0. 2. 4. 6. 8.]\n\nprint(np.nan == np.nan) # False! isnan을 써야 한다","cap":"같은 seed의 Generator는 같은 수열을 재현하고, out=은 결과를 기존 배열에 직접 쓴다."},"key":["ufunc는 원소별 연산을 C 루프로 처리해 파이썬 for문보다 훨씬 빠르다.","out= 인자로 결과를 기존 배열에 써서 새 할당을 줄일 수 있다.","재현성은 np.random.default_rng(seed) Generator가 권장 방식이고, 전역 seed는 간섭 위험이 있다.","같은 seed라도 호출 순서·횟수가 바뀌면 나오는 값이 달라진다.","np.nan == np.nan은 False이고, 정수 dtype은 범위를 넘으면 wrap around 된다."]}},{"t":"난수와 재현성","q":[{"t":"choice","k":"권장 방식","q":"현재 NumPy에서 재현 가능한 난수를 만드는 권장 방식은?","ex":"np.random.default_rng(seed)가 만드는 Generator는 자체 상태를 들고 있어 전역 간섭이 없고 통계적 품질도 개선되어 있다. np.random.seed 계열은 레거시 전역 API이고, 매번 시간으로 seed를 바꾸면 재현성 자체가 사라진다.","o":["np.random.seed(42) 후 np.random.rand() 사용","rng = np.random.default_rng(42) 후 rng.random() 사용","표준 라이브러리 random.seed(42) 후 random.random() 사용","매 호출 전에 np.random.seed(time.time()) 호출"],"a":1},{"t":"input","k":"Generator 생성","q":"시드 42로 NumPy Generator를 만드는 표준 코드를 쓰시오. (np는 numpy를 import한 별칭)","ex":"np.random.default_rng(42)는 지정한 seed로 초기화된 Generator 객체를 돌려준다. 이후 rng.random(), rng.integers(), rng.normal() 등을 이 객체를 통해 호출한다.","a":["np.random.default_rng(42)","default_rng(42)","numpy.random.default_rng(42)","rng = np.random.default_rng(42)"]},{"t":"choice","k":"seed 오개념","q":"시드를 한 번 고정하면 이후 난수 호출이 어떻게 되는가?","ex":"seed는 난수 수열의 시작점을 정할 뿐이고, 호출할 때마다 수열의 다음 부분이 소비된다. 그래서 중간에 호출을 하나 추가하거나 순서를 바꾸면 이후 값이 전부 달라진다. 같은 결과를 원하면 코드 실행 순서까지 동일해야 한다.","o":["이후 모든 난수 호출이 같은 값을 반복해서 낸다","난수가 완전히 고정되어 배열 크기나 호출 방식과 무관하게 같은 값이 나온다","seed는 성능 최적화 용도라 나오는 값에는 영향이 없다","정해진 난수열을 앞에서부터 꺼내 쓰므로 호출 순서나 횟수가 바뀌면 값도 달라진다"],"a":3},{"t":"choice","k":"독립성","q":"rng_a = np.random.default_rng(1) 과 rng_b = np.random.default_rng(2) 를 각각 사용할 때 옳은 설명은?","ex":"Generator는 각자 내부 상태를 들고 있는 독립 객체다. 그래서 모듈별, 실험별로 Generator를 따로 만들어 쓰면 서로 간섭 없이 각각 재현할 수 있다. 이것이 전역 시드 대비 가장 큰 장점이다.","o":["한쪽에서 난수를 뽑으면 다른 쪽의 수열도 함께 진행된다","서로 상태가 독립이라 한쪽 호출이 다른 쪽에 영향을 주지 않는다","두 Generator는 결국 같은 전역 상태를 공유한다","seed가 서로 다르면 예외가 발생한다"],"a":1}],"th":{"sum":"ufunc는 원소별 연산을 C 루프로 돌려 파이썬 for문보다 훨씬 빠르고, out= 인자로 메모리 할당까지 줄일 수 있다. 난수는 np.random.default_rng(seed)로 만든 Generator를 쓰는 것이 재현성과 독립성을 함께 얻는 권장 방식이다.","body":[{"h":"ufunc와 벡터화","t":"`np.add`, `np.sqrt`, `np.exp` 같은 **유니버설 함수(ufunc)**는 배열 원소마다 동작하는 연산을 C 레벨 루프로 수행한다. 파이썬 `for` 루프는 원소마다 객체 생성과 인터프리터 오버헤드가 붙지만 ufunc에는 그 비용이 없어 훨씬 빠르다. `a + b`, `a * 2` 같은 연산자 표현도 내부적으로는 ufunc 호출로 이어진다."},{"h":"out=으로 할당 줄이기","t":"ufunc는 `out=` 인자를 받아 결과를 이미 존재하는 배열에 직접 기록한다. `np.multiply(a, 2, out=a)`처럼 쓰면 새 배열을 만들지 않아 큰 데이터에서 메모리와 시간을 아낄 수 있다. ufunc는 `reduce`, `accumulate` 같은 메서드도 제공해서 `np.add.reduce(x)`는 합, `np.add.accumulate(x)`는 누적합이 된다."},{"h":"Generator가 권장 방식이다","t":"재현 가능한 난수는 `rng = np.random.default_rng(42)`로 Generator를 만들어 `rng.random()`, `rng.integers()`를 호출하는 것이 권장 방식이다. 레거시인 `np.random.seed(42)` + `np.random.rand()`는 **전역 상태**를 공유해서, 다른 라이브러리가 같은 전역 난수를 소비하면 결과가 달라질 수 있다. Generator는 객체마다 상태를 따로 들고 있어 그런 간섭이 없다."},{"h":"같은 seed, 같은 순서라야 같은 값","t":"같은 seed로 만든 Generator는 같은 순서의 난수열을 재현한다. 하지만 **호출 순서나 횟수가 바뀌면 값도 달라진다**. seed를 한 번 정했다고 이후 모든 호출이 같은 값을 내는 것이 아니라, 정해진 수열을 앞에서부터 차례로 꺼내 쓰는 구조다."},{"h":"수치 함정: NaN과 정수 오버플로","t":"부동소수 `np.nan`은 자기 자신과도 같지 않아 `np.nan == np.nan`은 `False`다. 결측 판별은 반드시 `np.isnan()`을 써야 하고, 합계 등은 `np.nansum` 같은 nan 무시 함수를 쓴다. 정수 dtype은 범위를 넘으면 예외 없이 **wrap around** 되어 `np.int8`에서 100 + 100은 -56이 된다."}],"code":{"c":"import numpy as np\n\nrng = np.random.default_rng(42)\nprint(rng.random(3))    # [0.77395605 0.43887844 0.85859792]\n\nrng2 = np.random.default_rng(42)\nprint(rng2.random(3))   # 같은 seed -> 같은 수열 재현\n\nx = np.arange(5.0)\nout = np.empty(5)\nnp.multiply(x, 2, out=out)   # 새 배열 할당 없이 out에 기록\nprint(out)              # [0. 2. 4. 6. 8.]\n\nprint(np.nan == np.nan) # False! isnan을 써야 한다","cap":"같은 seed의 Generator는 같은 수열을 재현하고, out=은 결과를 기존 배열에 직접 쓴다."},"key":["ufunc는 원소별 연산을 C 루프로 처리해 파이썬 for문보다 훨씬 빠르다.","out= 인자로 결과를 기존 배열에 써서 새 할당을 줄일 수 있다.","재현성은 np.random.default_rng(seed) Generator가 권장 방식이고, 전역 seed는 간섭 위험이 있다.","같은 seed라도 호출 순서·횟수가 바뀌면 나오는 값이 달라진다.","np.nan == np.nan은 False이고, 정수 dtype은 범위를 넘으면 wrap around 된다."]}},{"t":"수치 함정: NaN과 오버플로","q":[{"t":"choice","k":"nan 비교","q":"np.nan == np.nan 의 결과는?","ex":"IEEE 754 규격상 NaN은 자기 자신을 포함해 어떤 값과도 같지 않다. 그래서 == 비교로는 결측을 절대 찾을 수 없고 결과는 False다.","o":["True","None","False","예외가 발생한다"],"a":2},{"t":"input","k":"nan 판별","q":"배열에서 NaN 여부를 판별할 때 써야 하는 NumPy 함수 이름은?","ex":"np.isnan(arr)는 원소별로 NaN이면 True인 불리언 배열을 돌려준다. == 비교 대신 반드시 이 함수를 써야 결측을 정확히 찾을 수 있다.","a":["np.isnan","isnan","np.isnan()","numpy.isnan"]},{"t":"choice","k":"nan 전파","q":"아래 코드의 출력은?","ex":"NaN이 하나라도 섞이면 산술 연산 결과 전체로 전파되어 nan이 된다. NaN을 무시하고 합을 구하려면 np.nansum(a)를 써야 하며 그 결과가 4.0이다.","code":"import numpy as np\na = np.array([1.0, np.nan, 3.0])\nprint(a.sum())","o":["nan","4.0","0.0","ValueError가 발생한다"],"a":0},{"t":"choice","k":"정수 오버플로","q":"아래 코드의 출력은?","ex":"int8은 -128~127만 표현하므로 200은 담을 수 없고 wrap around 되어 200 - 256 = -56이 된다. 127로 잘리는 saturation이 아니라 순환이며, 예외도 발생하지 않아 조용히 틀린 값이 나온다.","code":"import numpy as np\nx = np.array([100, 100], dtype=np.int8)\nprint(x + x)","o":["[200 200]","[127 127]","OverflowError가 발생한다","[-56 -56]"],"a":3}],"th":{"sum":"ufunc는 원소별 연산을 C 루프로 돌려 파이썬 for문보다 훨씬 빠르고, out= 인자로 메모리 할당까지 줄일 수 있다. 난수는 np.random.default_rng(seed)로 만든 Generator를 쓰는 것이 재현성과 독립성을 함께 얻는 권장 방식이다.","body":[{"h":"ufunc와 벡터화","t":"`np.add`, `np.sqrt`, `np.exp` 같은 **유니버설 함수(ufunc)**는 배열 원소마다 동작하는 연산을 C 레벨 루프로 수행한다. 파이썬 `for` 루프는 원소마다 객체 생성과 인터프리터 오버헤드가 붙지만 ufunc에는 그 비용이 없어 훨씬 빠르다. `a + b`, `a * 2` 같은 연산자 표현도 내부적으로는 ufunc 호출로 이어진다."},{"h":"out=으로 할당 줄이기","t":"ufunc는 `out=` 인자를 받아 결과를 이미 존재하는 배열에 직접 기록한다. `np.multiply(a, 2, out=a)`처럼 쓰면 새 배열을 만들지 않아 큰 데이터에서 메모리와 시간을 아낄 수 있다. ufunc는 `reduce`, `accumulate` 같은 메서드도 제공해서 `np.add.reduce(x)`는 합, `np.add.accumulate(x)`는 누적합이 된다."},{"h":"Generator가 권장 방식이다","t":"재현 가능한 난수는 `rng = np.random.default_rng(42)`로 Generator를 만들어 `rng.random()`, `rng.integers()`를 호출하는 것이 권장 방식이다. 레거시인 `np.random.seed(42)` + `np.random.rand()`는 **전역 상태**를 공유해서, 다른 라이브러리가 같은 전역 난수를 소비하면 결과가 달라질 수 있다. Generator는 객체마다 상태를 따로 들고 있어 그런 간섭이 없다."},{"h":"같은 seed, 같은 순서라야 같은 값","t":"같은 seed로 만든 Generator는 같은 순서의 난수열을 재현한다. 하지만 **호출 순서나 횟수가 바뀌면 값도 달라진다**. seed를 한 번 정했다고 이후 모든 호출이 같은 값을 내는 것이 아니라, 정해진 수열을 앞에서부터 차례로 꺼내 쓰는 구조다."},{"h":"수치 함정: NaN과 정수 오버플로","t":"부동소수 `np.nan`은 자기 자신과도 같지 않아 `np.nan == np.nan`은 `False`다. 결측 판별은 반드시 `np.isnan()`을 써야 하고, 합계 등은 `np.nansum` 같은 nan 무시 함수를 쓴다. 정수 dtype은 범위를 넘으면 예외 없이 **wrap around** 되어 `np.int8`에서 100 + 100은 -56이 된다."}],"code":{"c":"import numpy as np\n\nrng = np.random.default_rng(42)\nprint(rng.random(3))    # [0.77395605 0.43887844 0.85859792]\n\nrng2 = np.random.default_rng(42)\nprint(rng2.random(3))   # 같은 seed -> 같은 수열 재현\n\nx = np.arange(5.0)\nout = np.empty(5)\nnp.multiply(x, 2, out=out)   # 새 배열 할당 없이 out에 기록\nprint(out)              # [0. 2. 4. 6. 8.]\n\nprint(np.nan == np.nan) # False! isnan을 써야 한다","cap":"같은 seed의 Generator는 같은 수열을 재현하고, out=은 결과를 기존 배열에 직접 쓴다."},"key":["ufunc는 원소별 연산을 C 루프로 처리해 파이썬 for문보다 훨씬 빠르다.","out= 인자로 결과를 기존 배열에 써서 새 할당을 줄일 수 있다.","재현성은 np.random.default_rng(seed) Generator가 권장 방식이고, 전역 seed는 간섭 위험이 있다.","같은 seed라도 호출 순서·횟수가 바뀌면 나오는 값이 달라진다.","np.nan == np.nan은 False이고, 정수 dtype은 범위를 넘으면 wrap around 된다."]}}]},{"t":"코드 리뷰 — 결함 찾기","l":[{"t":"코드 리뷰 I","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"def normalize(a):\n    a -= a.mean()\n    a /= a.std()\n    return a\n\nx = np.array([1., 2., 3.])\ny = normalize(x)","items":[{"txt":"제자리 연산으로 인자를 직접 수정한다. 호출자의 x 도 함께 바뀌어 원본을 잃는다.","bad":true},{"txt":"입력을 바꾸는 함수는 예상하지 못한 부수효과를 만든다. a = a - a.mean() 처럼 새 배열을 만들거나 명시적으로 copy 해야 한다.","bad":true},{"txt":"std 가 0 인 배열(모두 같은 값)에서 0 나눗셈이 발생해 inf/nan 이 된다.","bad":true},{"txt":"함수 인자로 전달된 배열은 값 복사되므로 원본이 변경되지 않는다.","bad":false},{"txt":"-= 는 새 배열을 만들므로 제자리 연산이 아니다.","bad":false},{"txt":"정수 배열을 넘기면 예외가 나므로 float 로 변환하는 것이 핵심 결함이다.","bad":false}],"ex":"결함 3가지: (1)(2) 인자 제자리 수정 — NumPy 에서 가장 흔한 부수효과 버그다. (3) 0 표준편차. 디스트랙터: 배열은 참조로 전달된다. -= 는 제자리 연산이다. 정수 배열에 float 결과를 제자리 대입하면 실제로 예외가 나지만, 그건 (1)의 파생이고 핵심은 원본 파괴다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"b = a[2:5]\nb[0] = 99\nprint(a)","items":[{"txt":"기본 슬라이싱은 뷰를 반환하므로 b 수정이 a 에 반영된다. 독립 배열이 필요하면 a[2:5].copy() 를 써야 한다.","bad":true},{"txt":"NumPy 슬라이싱은 항상 사본을 반환하므로 a 는 변경되지 않는다.","bad":false},{"txt":"정수 인덱싱과 슬라이싱은 모두 사본을 만들므로 뷰 개념이 없다.","bad":false},{"txt":"b[0] 대신 b[0:1] 을 써야 원본에 반영되므로 코드가 의도대로 동작하지 않는다.","bad":false},{"txt":"a 가 C 연속이 아니면 슬라이싱이 실패하므로 ascontiguousarray 가 필요하다.","bad":false},{"txt":"뷰를 수정하면 예외가 발생하므로 이 코드는 실행되지 않는다.","bad":false}],"ex":"결함 1가지: 뷰와 사본의 혼동. 기본 슬라이싱은 뷰이고, 팬시 인덱싱(정수 배열·불리언 마스크)은 사본이다. 이 차이를 모르면 '왜 원본이 바뀌었는가' 와 '왜 원본이 안 바뀌었는가' 를 둘 다 겪는다. 디스트랙터: 슬라이싱은 뷰다. 팬시 인덱싱은 사본이라 종류에 따라 다르다. 뷰는 정상적으로 쓰기 가능하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"a = np.zeros((1000, 1000), dtype=np.int8)\na[:] = 200\nprint(a[0, 0])","items":[{"txt":"int8 의 범위는 -128~127 이라 200 이 오버플로해 -56 이 된다. 예외 없이 조용히 값이 바뀐다.","bad":true},{"txt":"dtype 범위 검증이 없다. 값 범위를 알고 dtype 을 고르거나 assert 로 확인해야 한다.","bad":true},{"txt":"NumPy 는 오버플로 시 예외를 던지므로 코드가 실행되지 않는다.","bad":false},{"txt":"int8 은 부호 없는 타입이라 0~255 를 담을 수 있어 200 이 정상 저장된다.","bad":false},{"txt":"a[:] = 200 은 브로드캐스팅 오류를 일으키므로 fill 을 써야 한다.","bad":false},{"txt":"zeros 로 만든 배열은 dtype 이 고정되지 않아 대입 시 자동 승격된다.","bad":false}],"ex":"결함 2가지: (1) 정수 오버플로의 조용한 랩어라운드. (2) 범위 검증 부재. NumPy 는 파이썬 정수와 달리 고정 폭이라 이 사고가 실제로 자주 일어난다. 디스트랙터: 오버플로는 경고 정도이고 예외가 아니다. uint8 이 0~255 이고 int8 은 부호 있는 타입이다. 스칼라 대입은 정상 브로드캐스팅된다. dtype 은 승격되지 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"a = np.array([1, 2, 3])       # shape (3,)\nb = np.array([[1], [2], [3]]) # shape (3, 1)\nprint((a + b).shape)          # 예상 (3,)","items":[{"txt":"브로드캐스팅으로 (3,1) 과 (3,) 이 (3,3) 이 된다. 의도가 요소별 덧셈이라면 형태를 맞춰야 한다.","bad":true},{"txt":"형태를 단정하지 않아 조용히 3×3 행렬이 만들어지고, 메모리와 이후 계산이 모두 어긋난다.","bad":true},{"txt":"서로 다른 차원 수의 배열은 브로드캐스팅되지 않아 예외가 발생한다.","bad":false},{"txt":"(3,) 과 (3,1) 은 같은 형태로 취급되므로 결과도 (3,) 이다.","bad":false},{"txt":"np.array 로 만든 배열은 항상 1차원이므로 b 의 형태가 잘못됐다.","bad":false},{"txt":"+ 연산은 형태가 다르면 앞쪽 배열의 형태를 따르므로 결과가 (3,) 이다.","bad":false}],"ex":"결함 2가지: 브로드캐스팅의 조용한 확장이다. 큰 배열에서는 (10000,) + (10000,1) 이 1억 원소 행렬을 만들어 메모리를 소진시킨다. reshape·ravel 로 형태를 명시하고 assert 로 단정한다. 디스트랙터: 차원 수가 달라도 뒤에서부터 맞으면 브로드캐스팅된다. (3,) 과 (3,1) 은 다른 형태다. b 는 2차원이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"total = 0\nfor i in range(len(a)):\n    total += a[i] * b[i]","items":[{"txt":"파이썬 루프로 요소별 곱의 합을 계산한다. np.dot(a, b) 나 (a*b).sum() 이 수십~수백 배 빠르다.","bad":true},{"txt":"스칼라 인덱싱마다 NumPy 스칼라 객체가 만들어져 오버헤드가 크다.","bad":true},{"txt":"a 와 b 의 길이가 다른 경우를 확인하지 않아, 짧은 쪽 기준으로 조용히 잘리거나 IndexError 가 난다.","bad":true},{"txt":"NumPy 배열은 파이썬 리스트보다 인덱싱이 빠르므로 루프도 충분히 빠르다.","bad":false},{"txt":"total 을 0 으로 초기화하면 dtype 이 파이썬 int 가 되어 정확도가 높아진다.","bad":false},{"txt":"np.dot 은 2차원 이상에서만 동작하므로 1차원 배열에는 쓸 수 없다.","bad":false}],"ex":"결함 3가지: (1) 벡터화 미사용. (2) 스칼라 접근 오버헤드. (3) 길이 검증 부재. 디스트랙터: NumPy 의 요소별 인덱싱은 리스트보다 느리다. 파이썬 int 누적은 오히려 느리다. np.dot 은 1차원에서 내적을 계산한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"if a == b:\n    print(\"같음\")","items":[{"txt":"배열 비교는 요소별 불리언 배열을 반환한다. if 에 넣으면 '진리값이 모호하다' 는 예외가 난다.","bad":true},{"txt":"의도가 전체 일치라면 np.array_equal(a, b) 를, 요소별 판정이라면 (a==b).all() 을 써야 한다.","bad":true},{"txt":"부동소수점 배열이라면 정확한 일치 비교 자체가 부적절하다. np.allclose 를 써야 한다.","bad":true},{"txt":"NumPy 는 배열 비교 시 자동으로 all() 을 적용하므로 정상 동작한다.","bad":false},{"txt":"== 비교는 형태가 다르면 브로드캐스팅되지 않아 항상 False 를 반환한다.","bad":false},{"txt":"배열이 비어 있으면 True 가 되어 조용히 통과하는 것이 유일한 결함이다.","bad":false}],"ex":"결함 3가지: (1) 진리값 모호 예외. (2) 의도 표현. (3) 부동소수점 비교. 디스트랙터: 자동 all() 은 없다(원소 1개 배열만 예외). 형태가 달라도 브로드캐스팅되며 안 되면 예외다. 빈 배열의 all() 은 True 지만 여기서는 예외가 먼저 난다."}],"th":{"sum":"NumPy 리뷰의 세 축: **뷰인가 사본인가 · 형태가 의도대로인가 · dtype 이 값을 담을 수 있는가.**","body":[{"h":"뷰와 사본, 그리고 제자리 연산","t":"기본 슬라이싱과 reshape·transpose 는 뷰이고, 팬시 인덱싱(정수 배열·불리언 마스크)과 flatten 은 사본이다. b = a 는 참조 바인딩일 뿐이다. -= 나 /= 같은 제자리 연산은 인자로 받은 배열을 그 자리에서 바꿔 호출자의 데이터를 파괴한다 — 입력을 바꾸는 함수는 명시적으로 copy() 로 시작한다. 반대로 큰 배열의 뷰를 들고 있으면 원본 버퍼가 해제되지 않는다."},{"h":"형태는 조용히 확장된다","t":"(3,) + (3,1) 은 예외가 아니라 (3,3) 이다. 큰 배열에서는 이 한 번의 브로드캐스팅이 메모리를 소진시킨다. axis 는 '그 축이 사라진다' 로 읽는다. where 는 인덱스 튜플을 반환하고, argsort 는 오름차순이며, dot 과 matmul 은 3차원 이상에서 다르게 동작한다. 형태를 assert 로 단정하면 이 부류가 대부분 잡힌다."},{"h":"dtype 은 값을 조용히 망친다","t":"NumPy 정수는 고정 폭이라 int8 에 200 을 넣으면 -56 이 되고, uint8 이미지에 2를 곱하면 밝은 픽셀이 어두워진다. 정수 배열에 나눗셈 결과를 대입하면 잘린다. empty 는 초기화하지 않아 쓰레기 값이 남고, float16 은 유효 자릿수가 3자리다. 예외가 나지 않기 때문에 테스트가 없으면 발견되지 않는다."},{"h":"부동소수점과 결측","t":"== 로 실수를 비교하지 않는다(allclose 의 rtol·atol). nan 은 집계를 전파하고 자기 자신과 같지 않으며 정렬에서 맨 뒤로 간다 — isnan 으로 먼저 점검한다. 3-시그마 이상치 탐지는 그 기준 자체가 이상치에 오염된다. 그리고 파이썬 루프·반복 concatenate 는 벡터 연산 대비 수백 배 느리고 이차 시간이 된다."}],"code":{"c":"# 결함: 인자 제자리 수정 + 브로드캐스팅 확장 + dtype 오버플로\ndef normalize(a):\n    a -= a.mean()          # 호출자의 배열이 파괴된다\n    a /= a.std()           # std==0 이면 inf\n    return a\n\nscores = np.array([1, 2, 3])          # int64\nw = np.array([[1], [2], [3]])         # (3,1)\ntotal = scores + w                    # 예상 (3,), 실제 (3,3)\nimg8 = img.astype(np.uint8) * 2       # 128 이상이 랩어라운드\n\n# 고침\ndef normalize(a):\n    a = np.asarray(a, dtype=np.float64).copy()   # 입력을 건드리지 않는다\n    s = a.std()\n    if s == 0:\n        return np.zeros_like(a)\n    return (a - a.mean()) / s\n\ntotal = scores + w.ravel()                       # 형태를 명시\nassert total.shape == scores.shape               # 의도를 코드로 고정\nimg8 = np.clip(img.astype(np.int16) * 2, 0, 255).astype(np.uint8)","cap":"입력은 복사하고, 형태는 단정하고, 계산은 넓은 타입에서"},"key":["슬라이싱·reshape 은 뷰, 팬시 인덱싱·flatten 은 사본. b = a 는 그냥 참조다","제자리 연산(-=, /=)은 인자를 파괴한다 — 입력을 바꿀 함수는 copy() 로 시작","(n,) 과 (n,1) 은 다른 형태다. 형태를 assert 로 단정하면 조용한 확장이 잡힌다","정수·uint8 은 예외 없이 랩어라운드한다. 넓은 타입에서 계산하고 clip 한다","empty 는 초기화하지 않는다. 실수 비교는 allclose, 결측은 isnan 으로 먼저 점검","파이썬 루프와 반복 concatenate 를 벡터 연산·사전 할당으로 바꾼다"]}},{"t":"코드 리뷰 II","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"big = np.random.rand(20000, 20000)\nresult = big @ big.T","items":[{"txt":"20000×20000 float64 는 약 3.2GB 다. 결과까지 더하면 메모리를 초과한다.","bad":true},{"txt":"행렬 곱의 계산량이 8×10¹² 회 수준이라 실행 시간도 비현실적이다. 블록 처리나 근사가 필요하다.","bad":true},{"txt":"float32 로 충분한 경우가 많은데 기본 float64 를 쓴다. 메모리가 절반이 된다.","bad":true},{"txt":"@ 연산자는 지연 평가되므로 결과가 실제로 필요할 때까지 메모리를 쓰지 않는다.","bad":false},{"txt":"big.T 는 사본을 만들므로 메모리가 두 배가 되는 것이 핵심 원인이다.","bad":false},{"txt":"random.rand 는 희소 배열을 반환하므로 실제 메모리 사용량이 훨씬 작다.","bad":false}],"ex":"결함 3가지: (1) 메모리 초과. (2) 계산량. (3) 불필요한 정밀도. 디스트랙터: NumPy 는 즉시 평가한다. .T 는 뷰이므로 추가 메모리를 쓰지 않는다. rand 는 밀집 배열이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"mask = a &gt; 0\na[mask] = a[mask] / a[mask].sum()","items":[{"txt":"a 가 정수 dtype 이면 나눗셈 결과가 float 인데 정수 배열에 대입하며 잘려 대부분 0 이 된다.","bad":true},{"txt":"a[mask].sum() 이 0 이면 0 나눗셈이 발생한다.","bad":true},{"txt":"팬시 인덱싱을 세 번 수행해 사본을 여러 번 만든다. 부분 배열을 한 번 꺼내 계산하는 편이 효율적이다.","bad":true},{"txt":"불리언 마스크 인덱싱은 뷰를 반환하므로 대입이 필요 없다.","bad":false},{"txt":"a[mask] 는 항상 float 로 승격되므로 dtype 문제가 없다.","bad":false},{"txt":"마스크로 선택한 원소가 없으면 예외가 발생해 코드가 중단된다.","bad":false}],"ex":"결함 3가지: (1) 정수 dtype 절단 — 조용히 0 이 된다. (2) 0 나눗셈. (3) 반복 사본. 디스트랙터: 불리언 인덱싱은 사본을 반환하지만 대입 형태(a[mask] = ...)는 원본을 갱신한다. dtype 은 승격되지 않는다. 빈 선택은 예외 없이 넘어간다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"np.random.seed(42)\nX = np.random.randn(100, 5)\n# 다른 모듈\nnp.random.shuffle(X)","items":[{"txt":"전역 난수 상태를 쓴다. 다른 모듈이 난수를 소비하면 결과가 달라져 재현되지 않는다. default_rng 로 생성기를 명시해야 한다.","bad":true},{"txt":"shuffle 은 첫 축만 섞고 제자리에서 수정한다. X 를 다른 곳에서 참조하고 있으면 예상 밖의 변경이 된다.","bad":true},{"txt":"레이블이 있다면 X 만 섞어 대응 관계가 깨진다. 인덱스를 섞어 함께 적용해야 한다.","bad":true},{"txt":"np.random.seed 를 호출하면 모듈 간에도 상태가 격리되므로 재현이 보장된다.","bad":false},{"txt":"shuffle 은 새 배열을 반환하므로 X 는 변경되지 않는다.","bad":false},{"txt":"randn 은 정규분포이므로 섞을 필요가 없어 shuffle 호출 자체가 불필요하다.","bad":false}],"ex":"결함 3가지: (1) 전역 난수 상태. (2) 제자리 수정. (3) 대응 관계 파괴. 디스트랙터: seed 는 전역 상태를 설정하므로 격리되지 않는다. shuffle 은 None 을 반환하고 제자리에서 섞는다. 순서를 섞는 것은 분포와 무관한 필요다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"print(0.1 + 0.2 == 0.3)          # False\nassert result == expected","items":[{"txt":"부동소수점을 == 로 비교한다. 이진 표현 오차 때문에 논리적으로 같은 값이 다르게 판정된다.","bad":true},{"txt":"허용 오차를 정하지 않았다. np.isclose 나 np.allclose 로 상대·절대 오차를 명시해야 한다.","bad":true},{"txt":"NumPy 의 == 는 자동으로 허용 오차를 적용하므로 파이썬 float 과 다르게 동작한다.","bad":false},{"txt":"assert 는 부동소수점 비교에서 항상 통과하므로 검증 효과가 없다.","bad":false},{"txt":"float64 는 정밀도가 충분하므로 == 비교가 안전하다.","bad":false},{"txt":"0.1 + 0.2 는 0.3 과 정확히 같으므로 첫 줄의 출력이 잘못됐다.","bad":false}],"ex":"결함 2가지: (1) 부동소수점 등가 비교. (2) 허용 오차 미정의. allclose 의 rtol·atol 을 문제 규모에 맞게 정하는 것이 핵심이다. 디스트랙터: NumPy 의 == 도 정확 비교다. assert 는 실패한다. 정밀도가 높아도 이진 표현 한계는 그대로다. 0.1+0.2 는 0.30000000000000004 다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"a = np.empty((100, 100))\nfor i in range(100):\n    a[i] = compute(i)","items":[{"txt":"empty 는 초기화하지 않으므로, compute 가 예외를 던지거나 일부 행을 채우지 못하면 쓰레기 값이 남는다.","bad":true},{"txt":"쓰레기 값은 nan 이 아니라 임의의 실수라 검증에서도 잡히지 않는다. zeros 나 full(nan) 이 안전하다.","bad":true},{"txt":"empty 는 0 으로 초기화하므로 미할당 행은 0 이 된다.","bad":false},{"txt":"반복문으로 행을 채우면 벡터화되지 않아 느린 것이 유일한 결함이다.","bad":false},{"txt":"a[i] = compute(i) 는 형태가 맞지 않으면 조용히 잘리므로 검증이 필요하다.","bad":false},{"txt":"empty 는 메모리를 예약만 하므로 대입 전에는 접근할 수 없다.","bad":false}],"ex":"결함 2가지: (1) 미초기화 메모리. (2) 쓰레기 값의 탐지 불가 — nan 으로 채우면 미할당 구간이 즉시 드러난다. 디스트랙터: empty 는 초기화하지 않는다. 성능은 부차적이다. 형태 불일치는 예외를 던진다. 미초기화 메모리도 읽을 수 있다(그게 위험이다)."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"idx = np.argsort(scores)\ntop = data[idx[:10]]","items":[{"txt":"argsort 는 오름차순이므로 상위가 아니라 하위 10개를 고른다. 내림차순이 필요하면 -scores 를 정렬하거나 뒤에서 잘라야 한다.","bad":true},{"txt":"전체 정렬은 O(n log n) 이다. 상위 k 개만 필요하면 argpartition 이 O(n) 이다.","bad":true},{"txt":"동점 처리 기준이 없다. 기본 정렬은 안정성이 보장되지 않아 실행마다 순서가 달라질 수 있다.","bad":true},{"txt":"argsort 는 기본적으로 내림차순이므로 상위 10개가 올바르게 선택된다.","bad":false},{"txt":"data[idx[:10]] 는 뷰를 반환하므로 원본을 수정하면 함께 바뀐다.","bad":false},{"txt":"scores 에 nan 이 있으면 argsort 가 예외를 던지므로 사전 처리가 필요하다.","bad":false}],"ex":"결함 3가지: (1) 정렬 방향 — 조용히 최악의 10개를 고른다. (2) 불필요한 전체 정렬. (3) 동점 비결정성(kind=\"stable\" 로 고정). 디스트랙터: argsort 는 오름차순이다. 팬시 인덱싱은 사본이다. nan 은 예외 없이 맨 뒤로 정렬된다."}],"th":{"sum":"NumPy 리뷰의 세 축: **뷰인가 사본인가 · 형태가 의도대로인가 · dtype 이 값을 담을 수 있는가.**","body":[{"h":"뷰와 사본, 그리고 제자리 연산","t":"기본 슬라이싱과 reshape·transpose 는 뷰이고, 팬시 인덱싱(정수 배열·불리언 마스크)과 flatten 은 사본이다. b = a 는 참조 바인딩일 뿐이다. -= 나 /= 같은 제자리 연산은 인자로 받은 배열을 그 자리에서 바꿔 호출자의 데이터를 파괴한다 — 입력을 바꾸는 함수는 명시적으로 copy() 로 시작한다. 반대로 큰 배열의 뷰를 들고 있으면 원본 버퍼가 해제되지 않는다."},{"h":"형태는 조용히 확장된다","t":"(3,) + (3,1) 은 예외가 아니라 (3,3) 이다. 큰 배열에서는 이 한 번의 브로드캐스팅이 메모리를 소진시킨다. axis 는 '그 축이 사라진다' 로 읽는다. where 는 인덱스 튜플을 반환하고, argsort 는 오름차순이며, dot 과 matmul 은 3차원 이상에서 다르게 동작한다. 형태를 assert 로 단정하면 이 부류가 대부분 잡힌다."},{"h":"dtype 은 값을 조용히 망친다","t":"NumPy 정수는 고정 폭이라 int8 에 200 을 넣으면 -56 이 되고, uint8 이미지에 2를 곱하면 밝은 픽셀이 어두워진다. 정수 배열에 나눗셈 결과를 대입하면 잘린다. empty 는 초기화하지 않아 쓰레기 값이 남고, float16 은 유효 자릿수가 3자리다. 예외가 나지 않기 때문에 테스트가 없으면 발견되지 않는다."},{"h":"부동소수점과 결측","t":"== 로 실수를 비교하지 않는다(allclose 의 rtol·atol). nan 은 집계를 전파하고 자기 자신과 같지 않으며 정렬에서 맨 뒤로 간다 — isnan 으로 먼저 점검한다. 3-시그마 이상치 탐지는 그 기준 자체가 이상치에 오염된다. 그리고 파이썬 루프·반복 concatenate 는 벡터 연산 대비 수백 배 느리고 이차 시간이 된다."}],"code":{"c":"# 결함: 인자 제자리 수정 + 브로드캐스팅 확장 + dtype 오버플로\ndef normalize(a):\n    a -= a.mean()          # 호출자의 배열이 파괴된다\n    a /= a.std()           # std==0 이면 inf\n    return a\n\nscores = np.array([1, 2, 3])          # int64\nw = np.array([[1], [2], [3]])         # (3,1)\ntotal = scores + w                    # 예상 (3,), 실제 (3,3)\nimg8 = img.astype(np.uint8) * 2       # 128 이상이 랩어라운드\n\n# 고침\ndef normalize(a):\n    a = np.asarray(a, dtype=np.float64).copy()   # 입력을 건드리지 않는다\n    s = a.std()\n    if s == 0:\n        return np.zeros_like(a)\n    return (a - a.mean()) / s\n\ntotal = scores + w.ravel()                       # 형태를 명시\nassert total.shape == scores.shape               # 의도를 코드로 고정\nimg8 = np.clip(img.astype(np.int16) * 2, 0, 255).astype(np.uint8)","cap":"입력은 복사하고, 형태는 단정하고, 계산은 넓은 타입에서"},"key":["슬라이싱·reshape 은 뷰, 팬시 인덱싱·flatten 은 사본. b = a 는 그냥 참조다","제자리 연산(-=, /=)은 인자를 파괴한다 — 입력을 바꿀 함수는 copy() 로 시작","(n,) 과 (n,1) 은 다른 형태다. 형태를 assert 로 단정하면 조용한 확장이 잡힌다","정수·uint8 은 예외 없이 랩어라운드한다. 넓은 타입에서 계산하고 clip 한다","empty 는 초기화하지 않는다. 실수 비교는 allclose, 결측은 isnan 으로 먼저 점검","파이썬 루프와 반복 concatenate 를 벡터 연산·사전 할당으로 바꾼다"]}},{"t":"코드 리뷰 III","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"a = np.array([1, 2, 3])\na[5] = 10","items":[{"txt":"범위를 벗어난 인덱스에 대입해 IndexError 가 난다. NumPy 배열은 파이썬 리스트처럼 자동으로 늘어나지 않는다.","bad":true},{"txt":"배열 크기를 미리 정하거나 np.append·concatenate 로 새 배열을 만들어야 한다. 다만 반복 append 는 비용이 크다.","bad":true},{"txt":"NumPy 는 범위를 벗어난 대입 시 배열을 자동으로 확장한다.","bad":false},{"txt":"a[5] 읽기는 0 을 반환하지만 쓰기는 예외가 나므로 비대칭이 문제다.","bad":false},{"txt":"dtype 이 int64 라 5 라는 인덱스가 값으로 해석되어 조용히 무시된다.","bad":false},{"txt":"np.append 는 제자리 연산이라 반복 호출이 효율적이다.","bad":false}],"ex":"결함 2가지: (1) 범위 초과 대입. (2) 고정 크기 배열의 성질 이해. 디스트랙터: NumPy 는 확장하지 않는다. 읽기도 IndexError 다. 인덱스는 값으로 해석되지 않는다. append 는 매번 새 배열을 만들어 반복이 비싸다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"def sum_rows(m):\n    return m.sum(axis=1)\n\nprint(sum_rows(np.ones((3, 4))))   # 기대: 각 열의 합","items":[{"txt":"axis=1 은 열 방향으로 축약해 행별 합을 낸다. 열의 합을 원하면 axis=0 이어야 한다.","bad":true},{"txt":"축 의미를 주석과 코드가 다르게 말한다. 형태를 단정해 의도를 코드로 고정해야 한다.","bad":true},{"txt":"axis=1 은 행을 축으로 하므로 열의 합이 계산되어 주석이 맞다.","bad":false},{"txt":"sum 은 축 인자와 무관하게 전체 합을 반환한다.","bad":false},{"txt":"np.ones 로 만든 배열은 모든 값이 1 이라 축 방향과 관계없이 결과가 같다.","bad":false},{"txt":"함수 이름이 sum_rows 이므로 axis=1 이 올바르며 주석만 고치면 된다.","bad":false}],"ex":"결함 2가지: axis 방향 혼동과 의도-구현 불일치. 'axis=n 은 그 축이 사라진다' 로 외우면 헷갈리지 않는다. 디스트랙터: axis=1 은 두 번째 축을 축약한다. sum 은 축을 따른다. (3,4) 에서는 축에 따라 길이가 3 과 4 로 달라진다. 마지막은 그럴듯하지만 호출부 주석이 열의 합을 기대하므로 무엇이 진짜 의도인지 확인해야 한다 — 코드만 맞추는 것은 해결이 아니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"X = np.loadtxt(\"data.csv\", delimiter=\",\")\nprint(X.shape)","items":[{"txt":"헤더 행을 건너뛰지 않아 문자열 헤더에서 변환 오류가 나거나, skiprows 없이 읽으면 실패한다.","bad":true},{"txt":"결측값 처리 방법을 지정하지 않았다. 빈 필드가 있으면 예외가 난다(genfromtxt 가 필요하다).","bad":true},{"txt":"큰 파일에서 loadtxt 는 순수 파이썬 파서라 매우 느리다. pandas 나 np.load 가 빠르다.","bad":true},{"txt":"loadtxt 는 헤더를 자동으로 감지해 건너뛴다.","bad":false},{"txt":"delimiter 를 지정하면 결측이 0 으로 채워지므로 별도 처리가 불필요하다.","bad":false},{"txt":"loadtxt 는 dtype 을 자동 추론해 열마다 다른 타입을 만들 수 있다.","bad":false}],"ex":"결함 3가지: (1) 헤더 미처리. (2) 결측 처리 부재. (3) 성능. 디스트랙터: loadtxt 는 헤더를 자동 감지하지 않는다. 결측은 예외를 낸다. loadtxt 는 단일 dtype 을 만든다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"a = np.arange(10)\nb = a.reshape(2, 5)\nb[0, 0] = 99\nprint(a[0])       # 기대: 0","items":[{"txt":"reshape 은 가능하면 뷰를 반환하므로 b 수정이 a 에 반영된다. a[0] 은 99 가 된다.","bad":true},{"txt":"독립 배열이 필요하면 reshape 후 copy 하거나 처음부터 사본을 만들어야 한다.","bad":true},{"txt":"reshape 은 항상 새 배열을 만들므로 원본이 보호된다.","bad":false},{"txt":"arange 로 만든 배열은 읽기 전용이라 b 수정이 예외를 던진다.","bad":false},{"txt":"reshape(2, 5) 는 원소 수가 맞지 않아 예외가 발생한다.","bad":false},{"txt":"2차원으로 바꾸면 메모리 레이아웃이 달라져 뷰가 될 수 없다.","bad":false}],"ex":"결함 2가지: reshape 이 뷰가 될 수 있다는 점을 놓쳤다. ravel 은 뷰일 수 있고 flatten 은 항상 사본이라는 차이도 같은 계열이다. 디스트랙터: reshape 은 조건이 맞으면 뷰다. arange 결과는 쓰기 가능하다. 10 = 2×5 로 맞는다. C 연속 배열의 reshape 은 뷰가 된다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"result = np.concatenate([result, new_chunk])\n# 루프 안에서 1만 번","items":[{"txt":"매번 새 배열을 만들어 전체를 복사한다. 1만 번이면 이차 시간이 되어 사실상 멈춘다.","bad":true},{"txt":"리스트에 청크를 모아 두고 마지막에 한 번 concatenate 하는 방식이 맞다.","bad":true},{"txt":"최종 크기를 알 수 있다면 미리 할당한 배열에 슬라이스로 채우는 편이 가장 빠르다.","bad":true},{"txt":"concatenate 는 제자리 연산이라 재대입이 불필요하다.","bad":false},{"txt":"NumPy 배열은 동적 배열로 구현되어 append 가 상수 시간이다.","bad":false},{"txt":"루프 안에서 concatenate 를 호출하면 자동으로 지연 평가되어 마지막에 한 번만 실행된다.","bad":false}],"ex":"결함 3가지: (1) 반복 연결의 이차 비용. (2) 올바른 패턴 미사용. (3) 사전 할당 미고려. 디스트랙터: concatenate 는 새 배열을 반환한다. NumPy 배열은 고정 크기 연속 메모리다. 지연 평가는 없다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"img = img.astype(np.uint8)\nimg = img * 2","items":[{"txt":"uint8 에서 2를 곱하면 128 이상이 오버플로해 랩어라운드한다. 밝기 조정이 어두운 값으로 뒤집힌다.","bad":true},{"txt":"클리핑을 하지 않았다. np.clip(img.astype(np.int16) * 2, 0, 255).astype(np.uint8) 처럼 넓은 타입에서 계산해야 한다.","bad":true},{"txt":"astype 이 반올림이 아니라 절단이라, 앞선 float 연산 결과가 있었다면 값이 아래로 치우친다.","bad":true},{"txt":"uint8 곱셈은 자동으로 int16 으로 승격되므로 오버플로가 없다.","bad":false},{"txt":"np.uint8 은 0~65535 범위이므로 곱셈 결과가 안전하다.","bad":false},{"txt":"astype 은 값을 변경하지 않고 해석만 바꾸므로 정보 손실이 없다.","bad":false}],"ex":"결함 3가지: (1) 오버플로 랩어라운드. (2) 클리핑 부재. (3) 절단 방식. 이미지 처리에서 '밝게 했는데 검은 점이 생김' 의 원인이다. 디스트랙터: 배열 × 스칼라는 dtype 을 유지한다. uint8 은 0~255 다. astype 은 값을 변환하며 손실이 발생한다."}],"th":{"sum":"NumPy 리뷰의 세 축: **뷰인가 사본인가 · 형태가 의도대로인가 · dtype 이 값을 담을 수 있는가.**","body":[{"h":"뷰와 사본, 그리고 제자리 연산","t":"기본 슬라이싱과 reshape·transpose 는 뷰이고, 팬시 인덱싱(정수 배열·불리언 마스크)과 flatten 은 사본이다. b = a 는 참조 바인딩일 뿐이다. -= 나 /= 같은 제자리 연산은 인자로 받은 배열을 그 자리에서 바꿔 호출자의 데이터를 파괴한다 — 입력을 바꾸는 함수는 명시적으로 copy() 로 시작한다. 반대로 큰 배열의 뷰를 들고 있으면 원본 버퍼가 해제되지 않는다."},{"h":"형태는 조용히 확장된다","t":"(3,) + (3,1) 은 예외가 아니라 (3,3) 이다. 큰 배열에서는 이 한 번의 브로드캐스팅이 메모리를 소진시킨다. axis 는 '그 축이 사라진다' 로 읽는다. where 는 인덱스 튜플을 반환하고, argsort 는 오름차순이며, dot 과 matmul 은 3차원 이상에서 다르게 동작한다. 형태를 assert 로 단정하면 이 부류가 대부분 잡힌다."},{"h":"dtype 은 값을 조용히 망친다","t":"NumPy 정수는 고정 폭이라 int8 에 200 을 넣으면 -56 이 되고, uint8 이미지에 2를 곱하면 밝은 픽셀이 어두워진다. 정수 배열에 나눗셈 결과를 대입하면 잘린다. empty 는 초기화하지 않아 쓰레기 값이 남고, float16 은 유효 자릿수가 3자리다. 예외가 나지 않기 때문에 테스트가 없으면 발견되지 않는다."},{"h":"부동소수점과 결측","t":"== 로 실수를 비교하지 않는다(allclose 의 rtol·atol). nan 은 집계를 전파하고 자기 자신과 같지 않으며 정렬에서 맨 뒤로 간다 — isnan 으로 먼저 점검한다. 3-시그마 이상치 탐지는 그 기준 자체가 이상치에 오염된다. 그리고 파이썬 루프·반복 concatenate 는 벡터 연산 대비 수백 배 느리고 이차 시간이 된다."}],"code":{"c":"# 결함: 인자 제자리 수정 + 브로드캐스팅 확장 + dtype 오버플로\ndef normalize(a):\n    a -= a.mean()          # 호출자의 배열이 파괴된다\n    a /= a.std()           # std==0 이면 inf\n    return a\n\nscores = np.array([1, 2, 3])          # int64\nw = np.array([[1], [2], [3]])         # (3,1)\ntotal = scores + w                    # 예상 (3,), 실제 (3,3)\nimg8 = img.astype(np.uint8) * 2       # 128 이상이 랩어라운드\n\n# 고침\ndef normalize(a):\n    a = np.asarray(a, dtype=np.float64).copy()   # 입력을 건드리지 않는다\n    s = a.std()\n    if s == 0:\n        return np.zeros_like(a)\n    return (a - a.mean()) / s\n\ntotal = scores + w.ravel()                       # 형태를 명시\nassert total.shape == scores.shape               # 의도를 코드로 고정\nimg8 = np.clip(img.astype(np.int16) * 2, 0, 255).astype(np.uint8)","cap":"입력은 복사하고, 형태는 단정하고, 계산은 넓은 타입에서"},"key":["슬라이싱·reshape 은 뷰, 팬시 인덱싱·flatten 은 사본. b = a 는 그냥 참조다","제자리 연산(-=, /=)은 인자를 파괴한다 — 입력을 바꿀 함수는 copy() 로 시작","(n,) 과 (n,1) 은 다른 형태다. 형태를 assert 로 단정하면 조용한 확장이 잡힌다","정수·uint8 은 예외 없이 랩어라운드한다. 넓은 타입에서 계산하고 clip 한다","empty 는 초기화하지 않는다. 실수 비교는 allclose, 결측은 isnan 으로 먼저 점검","파이썬 루프와 반복 concatenate 를 벡터 연산·사전 할당으로 바꾼다"]}},{"t":"코드 리뷰 IV","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"cov = X.T @ X / len(X)\neigvals = np.linalg.eig(cov)[0]\nprint(eigvals[:3])","items":[{"txt":"평균을 빼지 않아 공분산이 아니라 2차 모멘트 행렬이다. 중심화가 필요하다.","bad":true},{"txt":"대칭 행렬에는 eigh 를 써야 한다. eig 는 일반 행렬용이라 복소수 결과와 정렬되지 않은 고윳값을 준다.","bad":true},{"txt":"고윳값이 정렬돼 있다고 가정하고 앞 3개를 잘랐다. eig 는 정렬을 보장하지 않는다.","bad":true},{"txt":"X.T @ X 는 항상 대칭이므로 eig 와 eigh 의 결과가 동일하다.","bad":false},{"txt":"len(X) 대신 len(X)-1 을 써야 하는 자유도 문제가 이 코드의 핵심 결함이다.","bad":false},{"txt":"linalg.eig 는 고윳값을 내림차순으로 반환하므로 슬라이싱이 안전하다.","bad":false}],"ex":"결함 3가지: (1) 중심화 누락. (2) 부적합한 분해 함수. (3) 정렬 가정. 디스트랙터: 대칭이어도 eig 는 수치 오차로 복소 성분을 낼 수 있고 정렬도 다르다. 자유도는 부차적이다. eig 는 정렬하지 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"a = np.array([[1, 2], [3, 4]])\nb = a\nb[0, 0] = 99\nprint(a[0, 0])   # 99\nprint(\"복사 완료\")","items":[{"txt":"대입은 참조만 복사한다. b 는 a 와 같은 객체이므로 수정이 그대로 반영된다. copy() 가 필요하다.","bad":true},{"txt":"주석과 출력이 '복사 완료' 라고 말하지만 실제로는 복사가 아니다. 의도와 코드가 어긋난다.","bad":true},{"txt":"NumPy 배열 대입은 얕은 복사를 수행하므로 최상위 요소만 공유한다.","bad":false},{"txt":"2차원 배열은 대입 시 자동으로 깊은 복사되므로 문제없다.","bad":false},{"txt":"b[0, 0] 대신 b[0][0] 을 쓰면 복사가 일어나 원본이 보호된다.","bad":false},{"txt":"copy.deepcopy 를 써야 하며 .copy() 는 뷰를 반환한다.","bad":false}],"ex":"결함 2가지: 참조 대입을 복사로 착각했다. .copy() 는 새 버퍼를 만든다. 디스트랙터: 대입은 참조 바인딩이다. 차원 수와 무관하다. b[0][0] 도 같은 버퍼를 가리킨다. .copy() 는 사본을 반환한다(deepcopy 는 불필요)."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"np.save(\"weights.npy\", model_weights)\nw = np.load(\"weights.npy\", allow_pickle=True)","items":[{"txt":"allow_pickle=True 는 임의 코드 실행을 허용한다. 신뢰할 수 없는 파일을 로드하면 위험하다.","bad":true},{"txt":"순수 수치 배열이라면 pickle 이 필요 없다. 필요하다는 것은 dtype=object 가 섞였다는 신호이므로 구조를 점검해야 한다.","bad":true},{"txt":"np.save 는 항상 pickle 을 쓰므로 allow_pickle 없이는 로드가 불가능하다.","bad":false},{"txt":"npy 형식은 dtype 을 저장하지 않아 로드 시 형태가 달라진다.","bad":false},{"txt":"np.load 는 메모리 매핑을 기본으로 쓰므로 큰 파일에서 메모리를 쓰지 않는다.","bad":false},{"txt":"weights.npy 확장자를 생략하면 np.save 가 실패한다.","bad":false}],"ex":"결함 2가지: (1) allow_pickle 의 보안 위험. (2) 그것이 필요한 이유를 점검하지 않음. 디스트랙터: 수치 배열은 pickle 없이 저장·로드된다. npy 는 dtype·형태를 헤더에 담는다. mmap_mode 를 지정해야 메모리 매핑된다. 확장자는 자동으로 붙는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"mean = data.mean()\nstd = data.std()\noutliers = data[np.abs(data - mean) &gt; 3 * std]","items":[{"txt":"평균과 표준편차 자체가 이상치에 크게 영향받는다. 이상치가 있으면 기준이 부풀려져 탐지에 실패한다. 중앙값·MAD 가 안정적이다.","bad":true},{"txt":"정규분포를 가정한 3-시그마 규칙인데 분포를 확인하지 않았다. 치우친 분포에서는 무의미하다.","bad":true},{"txt":"결측이 있으면 mean·std 가 nan 이 되어 조건이 전부 False 가 되고 이상치가 하나도 없다고 나온다.","bad":true},{"txt":"np.abs 대신 절댓값 없이 비교해야 양쪽 꼬리를 모두 잡을 수 있다.","bad":false},{"txt":"std 는 기본 ddof=1 이므로 모표준편차와 달라 기준이 엄격해진다.","bad":false},{"txt":"3 시그마는 통계적으로 확정된 기준이므로 분포 확인이 불필요하다.","bad":false}],"ex":"결함 3가지: (1) 이상치에 민감한 기준. (2) 분포 가정 미확인. (3) 결측의 조용한 전파. 디스트랙터: abs 가 양쪽을 잡는 올바른 방법이다. NumPy 의 std 기본 ddof 는 0 이다. 3 시그마는 정규분포 가정 아래의 관례다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"a = np.zeros(1_000_000)\nfor i in range(1_000_000):\n    a[i] = i ** 2","items":[{"txt":"파이썬 루프로 100만 번 대입한다. np.arange(1_000_000) ** 2 가 수백 배 빠르다.","bad":true},{"txt":"i ** 2 가 파이썬 정수 연산이라 매번 객체가 만들어진다.","bad":true},{"txt":"결과를 float64 배열에 담아 정수 정밀도가 필요한 경우 큰 값에서 오차가 생긴다.","bad":true},{"txt":"zeros 로 미리 할당했으므로 루프 대입이 벡터 연산과 성능이 같다.","bad":false},{"txt":"i ** 2 는 최대 10¹² 로 float64 가 표현할 수 없어 오버플로한다.","bad":false},{"txt":"range 를 np.arange 로 바꾸면 루프 자체가 벡터화된다.","bad":false}],"ex":"결함 3가지: (1) 벡터화 미사용. (2) 파이썬 객체 오버헤드. (3) dtype 부적합. 디스트랙터: 사전 할당은 재할당만 막고 루프 비용은 그대로다. float64 는 10¹² 를 정확히 표현한다(2⁵³ 까지 정수 정확). arange 로 바꿔도 파이썬 루프는 그대로다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"X_norm = (X - X.min()) / (X.max() - X.min())","items":[{"txt":"전체 배열의 최소·최대를 쓴다. 열별 정규화가 필요하면 axis=0 을 지정해야 한다.","bad":true},{"txt":"X.max() == X.min() 인 경우(상수 배열·상수 열) 0 나눗셈이 발생한다.","bad":true},{"txt":"학습 데이터의 min·max 를 저장하지 않아 서빙에서 같은 변환을 재현할 수 없다. 새 데이터의 범위로 다시 계산하면 값이 어긋난다.","bad":true},{"txt":"min-max 정규화는 이상치에 강건하므로 전처리로 항상 적합하다.","bad":false},{"txt":"NumPy 는 0 나눗셈에서 예외를 던지므로 상수 배열이 즉시 발견된다.","bad":false},{"txt":"결과가 0~1 범위이므로 이후 어떤 모델에도 그대로 쓸 수 있다.","bad":false}],"ex":"결함 3가지: (1) 축 미지정. (2) 0 나눗셈. (3) 변환 파라미터 미저장. 디스트랙터: min-max 는 이상치 하나에 범위가 좌우되어 강건하지 않다. NumPy 는 inf/nan 과 경고를 낸다. 새 데이터가 학습 범위를 벗어나면 0~1 을 넘는다."}],"th":{"sum":"NumPy 리뷰의 세 축: **뷰인가 사본인가 · 형태가 의도대로인가 · dtype 이 값을 담을 수 있는가.**","body":[{"h":"뷰와 사본, 그리고 제자리 연산","t":"기본 슬라이싱과 reshape·transpose 는 뷰이고, 팬시 인덱싱(정수 배열·불리언 마스크)과 flatten 은 사본이다. b = a 는 참조 바인딩일 뿐이다. -= 나 /= 같은 제자리 연산은 인자로 받은 배열을 그 자리에서 바꿔 호출자의 데이터를 파괴한다 — 입력을 바꾸는 함수는 명시적으로 copy() 로 시작한다. 반대로 큰 배열의 뷰를 들고 있으면 원본 버퍼가 해제되지 않는다."},{"h":"형태는 조용히 확장된다","t":"(3,) + (3,1) 은 예외가 아니라 (3,3) 이다. 큰 배열에서는 이 한 번의 브로드캐스팅이 메모리를 소진시킨다. axis 는 '그 축이 사라진다' 로 읽는다. where 는 인덱스 튜플을 반환하고, argsort 는 오름차순이며, dot 과 matmul 은 3차원 이상에서 다르게 동작한다. 형태를 assert 로 단정하면 이 부류가 대부분 잡힌다."},{"h":"dtype 은 값을 조용히 망친다","t":"NumPy 정수는 고정 폭이라 int8 에 200 을 넣으면 -56 이 되고, uint8 이미지에 2를 곱하면 밝은 픽셀이 어두워진다. 정수 배열에 나눗셈 결과를 대입하면 잘린다. empty 는 초기화하지 않아 쓰레기 값이 남고, float16 은 유효 자릿수가 3자리다. 예외가 나지 않기 때문에 테스트가 없으면 발견되지 않는다."},{"h":"부동소수점과 결측","t":"== 로 실수를 비교하지 않는다(allclose 의 rtol·atol). nan 은 집계를 전파하고 자기 자신과 같지 않으며 정렬에서 맨 뒤로 간다 — isnan 으로 먼저 점검한다. 3-시그마 이상치 탐지는 그 기준 자체가 이상치에 오염된다. 그리고 파이썬 루프·반복 concatenate 는 벡터 연산 대비 수백 배 느리고 이차 시간이 된다."}],"code":{"c":"# 결함: 인자 제자리 수정 + 브로드캐스팅 확장 + dtype 오버플로\ndef normalize(a):\n    a -= a.mean()          # 호출자의 배열이 파괴된다\n    a /= a.std()           # std==0 이면 inf\n    return a\n\nscores = np.array([1, 2, 3])          # int64\nw = np.array([[1], [2], [3]])         # (3,1)\ntotal = scores + w                    # 예상 (3,), 실제 (3,3)\nimg8 = img.astype(np.uint8) * 2       # 128 이상이 랩어라운드\n\n# 고침\ndef normalize(a):\n    a = np.asarray(a, dtype=np.float64).copy()   # 입력을 건드리지 않는다\n    s = a.std()\n    if s == 0:\n        return np.zeros_like(a)\n    return (a - a.mean()) / s\n\ntotal = scores + w.ravel()                       # 형태를 명시\nassert total.shape == scores.shape               # 의도를 코드로 고정\nimg8 = np.clip(img.astype(np.int16) * 2, 0, 255).astype(np.uint8)","cap":"입력은 복사하고, 형태는 단정하고, 계산은 넓은 타입에서"},"key":["슬라이싱·reshape 은 뷰, 팬시 인덱싱·flatten 은 사본. b = a 는 그냥 참조다","제자리 연산(-=, /=)은 인자를 파괴한다 — 입력을 바꿀 함수는 copy() 로 시작","(n,) 과 (n,1) 은 다른 형태다. 형태를 assert 로 단정하면 조용한 확장이 잡힌다","정수·uint8 은 예외 없이 랩어라운드한다. 넓은 타입에서 계산하고 clip 한다","empty 는 초기화하지 않는다. 실수 비교는 allclose, 결측은 isnan 으로 먼저 점검","파이썬 루프와 반복 concatenate 를 벡터 연산·사전 할당으로 바꾼다"]}},{"t":"코드 리뷰 V","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"idx = np.where(a &gt; 0)\nprint(\"개수:\", len(idx))","items":[{"txt":"where 는 축별 인덱스 배열의 튜플을 반환한다. 1차원 배열이면 길이가 항상 1 이므로 개수가 아니다.","bad":true},{"txt":"개수만 필요하면 (a &gt; 0).sum() 이나 np.count_nonzero(a &gt; 0) 가 명확하고 빠르다.","bad":true},{"txt":"where 는 인덱스 배열을 직접 반환하므로 len 이 개수와 같다.","bad":false},{"txt":"where 에 조건만 주면 예외가 발생하므로 세 인자를 모두 넘겨야 한다.","bad":false},{"txt":"a &gt; 0 은 불리언 배열이므로 sum 을 호출할 수 없다.","bad":false},{"txt":"count_nonzero 는 0 이 아닌 값의 개수만 세므로 조건 판정에 쓸 수 없다.","bad":false}],"ex":"결함 2가지: (1) 반환 구조 오해 — 조용히 1 이 출력된다. (2) 의도에 맞지 않는 도구. 디스트랙터: 튜플을 반환한다. 조건 하나만 주는 것은 정상 사용법이다. 불리언 배열의 sum 은 True 개수다. 불리언 배열에 count_nonzero 를 쓰면 True 개수를 센다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"a = np.array([1.0, 2.0, np.nan, 4.0])\nprint(a.mean())          # nan\nprint(a.max())           # nan\nprint(np.sort(a))","items":[{"txt":"결측이 있으면 mean·max 가 nan 을 전파한다. nanmean·nanmax 를 쓰거나 사전에 처리해야 한다.","bad":true},{"txt":"nan 의 존재를 확인하는 단계가 없다. np.isnan(a).any() 로 먼저 점검해야 한다.","bad":true},{"txt":"nan 이 있는 배열의 비교 기반 연산(정렬·argmax)은 결과가 직관과 다르다. nan 은 정렬에서 맨 뒤로 가고 argmax 는 nan 위치를 반환할 수 있다.","bad":true},{"txt":"NumPy 는 nan 을 자동으로 제외하고 계산하므로 결과가 정상이다.","bad":false},{"txt":"np.nan 은 float 이 아니므로 배열 dtype 이 object 가 되어 연산이 실패한다.","bad":false},{"txt":"nan 은 자기 자신과 같으므로 == 비교로 쉽게 찾을 수 있다.","bad":false}],"ex":"결함 3가지: (1) nan 전파. (2) 사전 점검 부재. (3) 비교 연산의 비직관성. 디스트랙터: 일반 집계는 nan 을 전파한다. np.nan 은 float 이라 dtype 은 float64 다. nan != nan 이므로 == 로 찾을 수 없다(isnan 이 필요하다)."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"result = np.dot(A, B)\nprint(result.shape)","items":[{"txt":"A 와 B 의 형태 호환성을 확인하지 않는다. 차원이 맞지 않으면 예외이고, 우연히 맞으면 의도와 다른 곱이 계산된다.","bad":true},{"txt":"3차원 이상에서 dot 과 matmul(@) 의 동작이 다르다. 배치 행렬 곱이 의도라면 @ 를 써야 한다.","bad":true},{"txt":"결과 형태를 단정하지 않아 조용히 잘못된 형태가 하류로 전달된다.","bad":true},{"txt":"np.dot 은 형태가 맞지 않으면 자동으로 브로드캐스팅하므로 항상 성공한다.","bad":false},{"txt":"dot 과 matmul 은 모든 차원에서 동일하게 동작하므로 구분이 불필요하다.","bad":false},{"txt":"shape 를 출력하면 형태가 검증되므로 assert 가 불필요하다.","bad":false}],"ex":"결함 3가지: (1) 형태 검증 부재. (2) dot vs matmul 차이. (3) 형태 단정 부재. 디스트랙터: dot 은 브로드캐스팅하지 않고 예외를 던진다. 3차원 이상에서 dot 은 텐서 축약, matmul 은 배치 곱이다. 출력은 확인이지 검증이 아니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"weights = np.random.randn(1000, 1000).astype(np.float16)\nout = weights @ x","items":[{"txt":"float16 은 유효 자릿수가 약 3자리로 매우 낮다. 큰 행렬 곱의 누적 오차가 커져 결과가 크게 어긋날 수 있다.","bad":true},{"txt":"float16 의 표현 범위가 좁아(최대 약 65504) 중간 계산에서 오버플로해 inf 가 될 수 있다.","bad":true},{"txt":"대부분의 CPU 는 float16 연산을 하드웨어로 지원하지 않아 오히려 느려진다. 메모리 이득만 있고 속도 이득이 없다.","bad":true},{"txt":"float16 은 float32 와 정밀도가 같고 메모리만 절반이므로 항상 유리하다.","bad":false},{"txt":"행렬 곱은 내부적으로 float64 로 누적하므로 dtype 과 무관하게 정확하다.","bad":false},{"txt":"astype 은 dtype 만 바꾸고 값은 유지하므로 정밀도 손실이 없다.","bad":false}],"ex":"결함 3가지: (1) 정밀도 부족. (2) 표현 범위. (3) CPU 성능. 저정밀도는 GPU 와 적절한 누적 타입이 함께 있을 때 의미가 있다. 디스트랙터: 정밀도가 다르다. 누적 타입은 구현에 따르며 자동 보장이 아니다. astype 은 값을 변환하며 손실이 발생한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"def f(x, cache={}):\n    if x not in cache:\n        cache[x] = np.linalg.inv(x)\n    return cache[x]","items":[{"txt":"배열을 딕셔너리 키로 쓰려 한다. NumPy 배열은 해시할 수 없어 TypeError 가 난다.","bad":true},{"txt":"가변 기본 인자를 캐시로 쓰면 호출 간에 상태가 유지되고 무한히 커진다.","bad":true},{"txt":"역행렬을 직접 구하는 것은 수치적으로 불안정하다. 방정식을 풀 목적이라면 solve 를 써야 한다.","bad":true},{"txt":"NumPy 배열은 내용 기반 해시를 지원하므로 캐시 키로 안전하다.","bad":false},{"txt":"기본 인자는 호출마다 새로 만들어지므로 상태가 누적되지 않는다.","bad":false},{"txt":"linalg.inv 는 특이 행렬에서 0 행렬을 반환하므로 예외 처리가 불필요하다.","bad":false}],"ex":"결함 3가지: (1) 배열을 해시 키로 사용. (2) 가변 기본 인자. (3) 역행렬 직접 계산. 디스트랙터: 배열은 해시 불가다. 기본 인자는 함수 정의 시 한 번 만들어진다. inv 는 특이 행렬에서 LinAlgError 를 던진다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"big = np.load(\"features.npy\")     # 40GB\nsub = big[:1000]\ndel big\nprocess(sub)","items":[{"txt":"40GB 를 메모리에 전부 올린다. mmap_mode=\"r\" 로 열면 필요한 부분만 읽는다.","bad":true},{"txt":"sub 은 big 의 뷰이므로 del big 으로도 원본 버퍼가 해제되지 않는다. 메모리가 그대로 붙잡혀 있다.","bad":true},{"txt":"일부만 쓸 것이 확실하면 처음부터 슬라이스를 사본으로 떠서 원본 참조를 끊어야 한다.","bad":true},{"txt":"del 은 즉시 메모리를 해제하므로 뷰가 있어도 원본이 반환된다.","bad":false},{"txt":"슬라이싱은 사본을 만들므로 뷰로 인한 메모리 유지는 발생하지 않는다.","bad":false},{"txt":"np.load 는 기본적으로 메모리 매핑을 쓰므로 40GB 를 올리지 않는다.","bad":false}],"ex":"결함 3가지: (1) 전체 로드. (2) 뷰가 원본을 붙잡음 — 눈에 잘 안 띄는 메모리 문제다. (3) 사본 미사용. 디스트랙터: 참조가 남아 있으면 해제되지 않는다. 기본 슬라이싱은 뷰다. np.load 의 기본은 메모리 매핑이 아니다."}],"th":{"sum":"NumPy 리뷰의 세 축: **뷰인가 사본인가 · 형태가 의도대로인가 · dtype 이 값을 담을 수 있는가.**","body":[{"h":"뷰와 사본, 그리고 제자리 연산","t":"기본 슬라이싱과 reshape·transpose 는 뷰이고, 팬시 인덱싱(정수 배열·불리언 마스크)과 flatten 은 사본이다. b = a 는 참조 바인딩일 뿐이다. -= 나 /= 같은 제자리 연산은 인자로 받은 배열을 그 자리에서 바꿔 호출자의 데이터를 파괴한다 — 입력을 바꾸는 함수는 명시적으로 copy() 로 시작한다. 반대로 큰 배열의 뷰를 들고 있으면 원본 버퍼가 해제되지 않는다."},{"h":"형태는 조용히 확장된다","t":"(3,) + (3,1) 은 예외가 아니라 (3,3) 이다. 큰 배열에서는 이 한 번의 브로드캐스팅이 메모리를 소진시킨다. axis 는 '그 축이 사라진다' 로 읽는다. where 는 인덱스 튜플을 반환하고, argsort 는 오름차순이며, dot 과 matmul 은 3차원 이상에서 다르게 동작한다. 형태를 assert 로 단정하면 이 부류가 대부분 잡힌다."},{"h":"dtype 은 값을 조용히 망친다","t":"NumPy 정수는 고정 폭이라 int8 에 200 을 넣으면 -56 이 되고, uint8 이미지에 2를 곱하면 밝은 픽셀이 어두워진다. 정수 배열에 나눗셈 결과를 대입하면 잘린다. empty 는 초기화하지 않아 쓰레기 값이 남고, float16 은 유효 자릿수가 3자리다. 예외가 나지 않기 때문에 테스트가 없으면 발견되지 않는다."},{"h":"부동소수점과 결측","t":"== 로 실수를 비교하지 않는다(allclose 의 rtol·atol). nan 은 집계를 전파하고 자기 자신과 같지 않으며 정렬에서 맨 뒤로 간다 — isnan 으로 먼저 점검한다. 3-시그마 이상치 탐지는 그 기준 자체가 이상치에 오염된다. 그리고 파이썬 루프·반복 concatenate 는 벡터 연산 대비 수백 배 느리고 이차 시간이 된다."}],"code":{"c":"# 결함: 인자 제자리 수정 + 브로드캐스팅 확장 + dtype 오버플로\ndef normalize(a):\n    a -= a.mean()          # 호출자의 배열이 파괴된다\n    a /= a.std()           # std==0 이면 inf\n    return a\n\nscores = np.array([1, 2, 3])          # int64\nw = np.array([[1], [2], [3]])         # (3,1)\ntotal = scores + w                    # 예상 (3,), 실제 (3,3)\nimg8 = img.astype(np.uint8) * 2       # 128 이상이 랩어라운드\n\n# 고침\ndef normalize(a):\n    a = np.asarray(a, dtype=np.float64).copy()   # 입력을 건드리지 않는다\n    s = a.std()\n    if s == 0:\n        return np.zeros_like(a)\n    return (a - a.mean()) / s\n\ntotal = scores + w.ravel()                       # 형태를 명시\nassert total.shape == scores.shape               # 의도를 코드로 고정\nimg8 = np.clip(img.astype(np.int16) * 2, 0, 255).astype(np.uint8)","cap":"입력은 복사하고, 형태는 단정하고, 계산은 넓은 타입에서"},"key":["슬라이싱·reshape 은 뷰, 팬시 인덱싱·flatten 은 사본. b = a 는 그냥 참조다","제자리 연산(-=, /=)은 인자를 파괴한다 — 입력을 바꿀 함수는 copy() 로 시작","(n,) 과 (n,1) 은 다른 형태다. 형태를 assert 로 단정하면 조용한 확장이 잡힌다","정수·uint8 은 예외 없이 랩어라운드한다. 넓은 타입에서 계산하고 clip 한다","empty 는 초기화하지 않는다. 실수 비교는 allclose, 결측은 isnan 으로 먼저 점검","파이썬 루프와 반복 concatenate 를 벡터 연산·사전 할당으로 바꾼다"]}}]},{"t":"실행형 실전 — 배열 연산을 직접 짠다","l":[{"t":"모양·축·곱·뷰","xp":80,"th":{"sum":"numpy 버그의 대부분은 계산식이 아니라 **모양(shape)** 에서 난다. 축을 잘못 잡거나 브로드캐스팅이 조용히 성공하는 것이 원인이다.","body":[{"h":"모양이 맞는 것과 의도한 것은 다르다","t":"브로드캐스팅은 **뒤에서부터** 짝을 맞추고 모자란 앞 차원은 1로 채운다. 그래서 `(5,)` 와 `(3,5)` 는 맞지만 `(5,)` 와 `(5,3)` 은 안 맞는다. 더 위험한 것은 **조용히 맞는** 경우다 — `(100,1)` 과 `(100,)` 을 더하면 오류 대신 `(100,100)` 이 되어 메모리를 만 배 쓴다."},{"h":"축과 메모리","t":"`axis` 는 '어느 축을 없앨 것인가' 다 — `(2,3)` 에서 `axis=0` 이면 `(3,)` 이 남는다. 정사각 행렬로만 테스트하면 축을 뒤집어도 모양이 맞아 못 잡는다. 그리고 numpy 의 기본 슬라이싱은 복사가 아니라 **뷰**라, 자른 배열을 고치면 원본이 바뀐다 — 파이썬 리스트와 정반대다."}],"code":{"c":"a = np.zeros((100,1)); b = np.zeros((100,))\n(a + b).shape   # (100, 100)  — 오류가 아니라 조용한 폭발","cap":"계산 전에 .shape 를 찍어 보는 습관"},"key":["브로드캐스팅은 뒤에서부터 — 조용히 맞는 경우가 가장 위험하다","`axis` 는 없앨 축 — 결과 모양으로 기억한다","행렬 곱은 안쪽 차원이 맞아야 하고 교환법칙이 없다","기본 슬라이싱은 뷰, 팬시·불리언 인덱싱은 복사","원본을 지키려면 `.copy()` 를 명시한다"]},"q":[{"t":"code","run":"js","k":"브로드캐스팅 규칙","cat":"internals","q":"두 배열의 <b>브로드캐스팅 결과 모양</b>을 계산하세요. 규칙: 뒤에서부터 짝을 맞추고, <b>같거나 한쪽이 1</b>이면 큰 쪽으로 늘어납니다. 맞지 않으면 <code>null</code> 입니다. 짧은 쪽 앞은 <b>1로 채웁니다</b>.","src":"function bshape(a, b) {\n  // TODO: 뒤에서부터 비교해 결과 모양을 만드세요\n  return null;\n}","sol":"function bshape(a, b) {\n  const n = Math.max(a.length, b.length);\n  const out = [];\n  for (let i = 0; i < n; i++) {\n    const x = a[a.length - 1 - i];\n    const y = b[b.length - 1 - i];\n    const dx = x === undefined ? 1 : x;\n    const dy = y === undefined ? 1 : y;\n    if (dx !== dy && dx !== 1 && dy !== 1) return null;\n    out.unshift(Math.max(dx, dy));\n  }\n  return out;\n}","tests":[{"in":"bshape([3,1],[3,4])","out":"[3,4]"},{"in":"bshape([5],[3,5])","out":"[3,5]"},{"in":"bshape([3,2],[3,4])","out":"null"},{"in":"bshape([2,1,3],[4,3])","out":"[2,4,3]"}],"edge":[{"in":"bshape([],[3])","out":"[3]"},{"in":"bshape([1],[1])","out":"[1]"}],"ex":"🎯 브로드캐스팅은 <b>뒤에서부터</b> 짝을 맞춥니다. 앞쪽 차원이 모자라면 1로 채워지므로 <code>(5,)</code> 와 <code>(3,5)</code> 는 맞고 <code>(5,)</code> 와 <code>(5,3)</code> 은 맞지 않습니다.\n💡 이 방향 때문에 '행 벡터를 각 행에 더하기' 는 자연스럽지만 '열 벡터를 각 열에 더하기' 는 <code>(n,1)</code> 로 <b>모양을 바꿔 줘야</b> 합니다. <code>reshape(-1,1)</code> 이 늘 등장하는 이유입니다.\n⚠️ 가장 위험한 것은 <b>조용히 맞는</b> 경우입니다. <code>(100,1)</code> 과 <code>(100,)</code> 를 더하면 오류가 아니라 <code>(100,100)</code> 이 되어 메모리를 만 배 씁니다 — 예측 결과와 정답의 모양이 어긋났을 때 흔히 일어납니다.\n🔧 그래서 계산 전에 <code>.shape</code> 를 찍어 보는 습관이 실제로 시간을 아낍니다."},{"t":"code","run":"js","k":"축을 따라 집계하기","cat":"internals","q":"2차원 배열에서 <code>axis</code> 를 따라 합을 구하세요. <code>sumAxis(m, axis)</code> 에서 <b>axis=0 은 행을 가로질러(열별 합)</b>, <b>axis=1 은 열을 가로질러(행별 합)</b> 입니다. <code>axis=null</code> 이면 전체 합입니다.","src":"function sumAxis(m, axis) {\n  // TODO: axis 0/1/null\n  return 0;\n}","sol":"function sumAxis(m, axis) {\n  if (axis === null) return m.reduce((s, r) => s + r.reduce((a, b) => a + b, 0), 0);\n  if (axis === 1) return m.map((r) => r.reduce((a, b) => a + b, 0));\n  return m[0].map((_, c) => m.reduce((s, r) => s + r[c], 0));\n}","tests":[{"in":"sumAxis([[1,2],[3,4]],0)","out":"[4,6]"},{"in":"sumAxis([[1,2],[3,4]],1)","out":"[3,7]"},{"in":"sumAxis([[1,2],[3,4]],null)","out":"10"},{"in":"sumAxis([[1,2,3]],0)","out":"[1,2,3]"}],"edge":[{"in":"sumAxis([[1,2,3]],1)","out":"[6]"},{"in":"sumAxis([[5]],null)","out":"5"}],"ex":"🎯 <code>axis</code> 는 '<b>어느 축을 없앨 것인가</b>' 입니다. <code>axis=0</code> 은 행 축이 사라져 열별 결과가 남고, <code>axis=1</code> 은 열 축이 사라져 행별 결과가 남습니다.\n💡 '축을 따라 계산한다' 를 '그 축 방향으로 훑는다' 로 읽으면 헷갈립니다. <b>결과의 모양</b>으로 기억하세요 — <code>(2,3)</code> 에서 <code>axis=0</code> 이면 <code>(3,)</code>, <code>axis=1</code> 이면 <code>(2,)</code> 입니다.\n⚠️ 이걸 뒤집으면 '샘플별 평균' 대신 '특성별 평균' 을 구하게 되는데, <b>모양이 우연히 맞으면 오류도 안 납니다</b>. 정사각 행렬로 테스트하면 못 잡으므로 이 문항의 테스트는 모두 비정사각입니다.\n🔧 <code>keepdims=True</code> 는 축을 없애지 않고 1로 남겨 브로드캐스팅이 그대로 되게 합니다 — 정규화할 때 특히 유용합니다."},{"t":"code","run":"js","k":"행렬 곱","cat":"internals","q":"행렬 곱 <code>matmul(a, b)</code> 를 구현하세요. <code>a</code> 가 <code>(n,k)</code>, <code>b</code> 가 <code>(k,m)</code> 이면 결과는 <code>(n,m)</code> 입니다. 안쪽 차원이 맞지 않으면 <code>null</code> 을 돌려주세요.","src":"function matmul(a, b) {\n  // TODO: 차원 검사 후 곱\n  return null;\n}","sol":"function matmul(a, b) {\n  if (!a.length || !b.length || a[0].length !== b.length) return null;\n  return a.map((row) =>\n    b[0].map((_, j) => row.reduce((s, v, k) => s + v * b[k][j], 0)));\n}","tests":[{"in":"matmul([[1,2],[3,4]],[[5,6],[7,8]])","out":"[[19,22],[43,50]]"},{"in":"matmul([[1,2,3]],[[1],[1],[1]])","out":"[[6]]"},{"in":"matmul([[1,2]],[[1,2],[3,4]])","out":"[[7,10]]"},{"in":"matmul([[1,2]],[[1,2]])","out":"null"}],"edge":[{"in":"matmul([[1,0],[0,1]],[[5,6],[7,8]])","out":"[[5,6],[7,8]]"},{"in":"matmul([],[[1]])","out":"null"}],"ex":"🎯 행렬 곱은 <b>안쪽 차원이 맞아야</b> 합니다 — <code>(n,k) × (k,m)</code>. 이 조건을 코드로 확인하지 않으면 잘못된 값이 조용히 계산됩니다.\n💡 결과 <code>(i,j)</code> 는 'a 의 i행과 b 의 j열의 내적' 입니다. 신경망의 한 층이 정확히 이 연산이고, 그래서 가중치 행렬의 모양이 <code>(입력 차원, 출력 차원)</code> 입니다.\n⚠️ 행렬 곱은 <b>교환법칙이 성립하지 않습니다</b>. <code>a×b</code> 와 <code>b×a</code> 는 모양부터 다를 수 있고, 둘 다 가능해도 값이 다릅니다 — 순서를 바꿔 '차원이 맞으니 됐다' 고 넘어가면 안 됩니다.\n🔧 <code>*</code> 는 요소별 곱이고 행렬 곱은 <code>@</code> 또는 <code>matmul</code> 입니다. 파이썬에서 이 둘을 혼동하면 브로드캐스팅 때문에 오류 없이 엉뚱한 결과가 나옵니다."},{"t":"code","run":"js","k":"뷰와 복사","cat":"internals","q":"배열 슬라이스가 <b>원본을 공유하는지</b> 확인하는 모델을 만드세요. <code>slice(arr, s, e)</code> 는 <b>뷰</b>(원본 공유)를 돌려주고, <code>copy(arr, s, e)</code> 는 독립된 배열을 돌려줍니다. 뷰에 값을 쓰면 원본도 바뀌어야 합니다.","src":"function slice(arr, s, e) {\n  // TODO: 원본을 공유하는 뷰 — {get, set, length}\n  return null;\n}\n\nfunction copy(arr, s, e) {\n  return arr.slice(s, e);\n}","sol":"function slice(arr, s, e) {\n  return {\n    length: e - s,\n    get(i) { return arr[s + i]; },\n    set(i, v) { arr[s + i] = v; },\n  };\n}\n\nfunction copy(arr, s, e) {\n  return arr.slice(s, e);\n}","tests":[{"in":"(() => { const a=[1,2,3,4]; const v=slice(a,1,3); v.set(0,99); return a; })()","out":"[1,99,3,4]"},{"in":"(() => { const a=[1,2,3,4]; const c=copy(a,1,3); c[0]=99; return a; })()","out":"[1,2,3,4]"},{"in":"(() => { const a=[1,2,3,4]; return slice(a,1,3).get(1); })()","out":"3"},{"in":"(() => { const a=[1,2,3,4]; return slice(a,1,3).length; })()","out":"2"}],"edge":[{"in":"(() => { const a=[1,2,3]; const v=slice(a,0,3); v.set(2,9); return a[2]; })()","out":"9"},{"in":"copy([1,2,3],0,0)","out":"[]"}],"ex":"🎯 numpy 의 기본 슬라이싱은 <b>복사가 아니라 뷰</b>입니다. <code>b = a[1:3]</code> 뒤에 <code>b[0] = 99</code> 하면 <b>a 도 바뀝니다</b> — 파이썬 리스트 슬라이싱과 정반대라 가장 자주 당하는 지점입니다.\n💡 뷰인 이유는 성능입니다. 큰 배열을 자를 때마다 복사하면 메모리와 시간이 배로 듭니다. 그래서 numpy 는 '같은 메모리를 다른 모양으로 보는' 것을 기본으로 삼습니다.\n⚠️ 반대로 <b>팬시 인덱싱</b>(<code>a[[0,2]]</code>)과 <b>불리언 인덱싱</b>은 복사입니다. 어떤 것이 뷰이고 어떤 것이 복사인지가 규칙으로 갈리므로, 헷갈리면 <code>.copy()</code> 를 명시하세요.\n🔧 원본을 지키고 싶으면 <code>.copy()</code>, 메모리를 아끼려면 뷰 — 이 선택을 코드에 드러내는 것이 나중의 디버깅 시간을 줄입니다."}]}]}]);
